BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('linux-q56', '環境変数とPATH',
   'シェルで一時的に使う「シェル変数」と、そのシェルから起動した別のプログラムにも値を渡せる「環境変数」がある。シェル変数を環境変数に変えるコマンドはどれか。',
   NULL::text,
   '["export（この変数を子プロセスにも見えるようにする）", "alias（コマンドに別名をつける）", "source（スクリプトを今のシェルで実行する）", "unset（変数を消す）"]',
   0, '[0]', 'single',
   '{"asked": "シェル変数を環境変数に切り替えるコマンドを選ぶ問題。", "point": "exportは「この値を、これから生まれる子プロセスにも見えるようにする」宣言。", "kid": "シェル変数は「今のシェルの中だけのメモ」。環境変数は「そのシェルから起動した別のプログラムにも渡せるメモ」。exportを付けると、メモが子プロセスにもコピーされるようになる。", "eg": "たとえるなら、シェル変数は自分の手帳に書いたメモ。exportすると、そのメモのコピーを「これから呼び出す部下（子プロセス）」全員に配るイメージ。部下は自分のメモとしてそれを読める。", "terms": [["シェル変数", "今のシェルの中だけで使える値"], ["環境変数", "子プロセスにも引き継がれる値。exportで作る"], ["子プロセス", "あるプロセスが起動した別のプロセス"]], "think": "なぜ2種類あるのかがカギ。シェルの中だけで使う一時的な値（ループのカウンタなど）まで全部子プロセスに渡すと、余計な情報だらけになる。だから「渡したい値だけexportで選ぶ」という仕組みになっている。exportされた変数だけが、子プロセスから見える。", "vs": "aliasと混同しやすいが、aliasはコマンドに短い別名をつけるだけで、値を子プロセスに渡す仕組みとは無関係。", "opt": ["正解。exportを付けた変数は環境変数になり、その後起動する子プロセスにも見えるようになる。", "aliasはコマンドの短縮名を作るだけで、変数を子プロセスに渡す仕組みではない。", "sourceはスクリプトの中身を今のシェルでそのまま実行するコマンドで、変数を環境変数に変える働きはない。", "unsetは変数そのものを消すコマンドで、環境変数に変える操作とは逆方向。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">シェル変数 vs 環境変数</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">シェル変数</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">今のシェルだけ</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">子プロセスに渡らない</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">環境変数(export後)</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">子プロセスにも渡る</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">起動したプログラムが読める</text></svg>"}'),

  ('linux-q57', '環境変数とPATH',
   'PATHに登録されていないディレクトリに置いた自作プログラムを実行したい。コマンド名だけを打っても「見つかりません」と言われてしまう。実行するために最低限必要なことはどれか。',
   NULL::text,
   '["ファイルの場所を./や絶対パスで明示して指定する", "そのプログラムのファイル名をすべて大文字にする", "OSを再起動してPATHを再読み込みさせる", "プログラムの拡張子を消す"]',
   0, '[0]', 'single',
   '{"asked": "PATHに登録されていない場所のプログラムを実行する方法を選ぶ問題。", "point": "PATHはあくまで「名前だけで探すときの候補地」。候補地に無いなら、自分で場所を教えてやればいい。", "kid": "シェルはコマンド名だけを打たれると、PATHに登録された決まった場所しか探さない。そこに無い場所のプログラムは、名前だけでは見つけてもらえない。だから「ここにあるよ」と場所そのもの（パス）を教えてあげる必要がある。", "eg": "たとえるなら、シェルは「決まった数軒の店（PATHのディレクトリ）」しか知らない御用聞き。その店以外にある自作の品物を届けてほしいなら、「◯◯町の△△さんの家にあります」と住所（パス）を直接教えるしかない。", "terms": [["PATH", "コマンド名だけで探すときに調べるディレクトリの一覧"], ["絶対パス/相対パス", "ファイルの場所そのものを示す書き方"]], "think": "なぜPATHに登録するだけが正解ではないのかがカギ。PATHへの登録は「今後も名前だけで何度も呼びたい」ときの恒久対応。今すぐ1回動かしたいだけなら、`./プログラム名`や絶対パスでファイルの場所を直接指定すれば、PATHを一切変更しなくても実行できる。つまりPATH登録は「あると便利」だが「無いと絶対に動かせない」わけではない。", "vs": "PATHへの追加と混同しやすいが、PATHに追加するのは「今後も名前だけで呼べるようにする」設定変更であり、その場しのぎで動かすだけなら場所を明示するほうが手軽。", "opt": ["正解。ファイルの場所を`./`や絶対パスで直接指定すれば、PATHに登録されていなくても実行できる。", "大文字小文字を変えても、シェルが探す場所（PATH）自体は変わらないので見つからない問題は解決しない。", "再起動してもPATHの中身自体は変わらないので、登録されていない場所は引き続き探されない。", "拡張子の有無はLinuxの実行判定に関係なく、探す場所の問題は解決しない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コマンド名だけ vs 場所を指定</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">linuxcmd</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">PATH内を検索</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">見つからず</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">エラー</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">./自作prog</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">場所を直接指定</text></svg>"}'),

  ('linux-q58', 'ジョブ管理とシグナル',
   '時間のかかるコマンドを実行しつつ、同じターミナルで別の作業も続けたい。コマンドの末尾に付けると、そのコマンドをバックグラウンドで動かしたまま操作を返してもらえる記号はどれか。',
   NULL::text,
   '["&（末尾に付けてバックグラウンド実行にする）", "|（2つのコマンドをつなぐ）", ">（出力をファイルに保存する）", ";（複数のコマンドを順番に並べる）"]',
   0, '[0]', 'single',
   '{"asked": "コマンドをバックグラウンドで動かす記号を選ぶ問題。", "point": "&は「このコマンドは裏で動かしておくので、すぐ次の操作をさせて」という合図。", "kid": "ふつうコマンドを実行すると、そのコマンドが終わるまでターミナルは次の入力を受け付けてくれない。末尾に`&`を付けると、そのコマンドを裏（バックグラウンド）に回して、すぐに次のコマンドを打てるようになる。", "eg": "たとえるなら、洗濯機を回している間、洗濯が終わるのを突っ立って待たずに、別の家事（次のコマンド）を始められるイメージ。`&`は「これは裏で回しておくね」という合図。", "terms": [["フォアグラウンド", "今ターミナルを占有して動いているプロセス"], ["バックグラウンド", "裏で動きつつ、ターミナルの操作は返してくれるプロセス"], ["ジョブ", "シェルが管理する実行中のコマンドの単位"]], "think": "なぜフォアグラウンドとバックグラウンドを分けるのかがカギ。1つのターミナルは基本、1つの作業に占有されると次の指示を受け付けられない。時間のかかる作業を全部フォアグラウンドで待っていると効率が悪い。`&`で裏に回すことで、待たずに次々と作業を進められる。", "vs": "パイプ`|`と混同しやすいが、パイプは「2つのコマンドの出力と入力をつなぐ」記号で、実行タイミング（裏で動かすかどうか）とは別の話。", "opt": ["正解。コマンドの末尾に`&`を付けると、そのコマンドはバックグラウンドで動き、すぐ次の操作ができる。", "`|`は前のコマンドの出力を次のコマンドの入力につなぐ記号で、バックグラウンド実行とは無関係。", "`>`は出力先をファイルに切り替える記号で、裏で動かすかどうかとは別の話。", "`;`は複数のコマンドを1行に順番に並べて実行する記号で、前のコマンドが終わるまで次は始まらない（バックグラウンドにはならない）。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">フォアグラウンド vs バックグラウンド</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コマンド実行</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">&なし=待つ</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コマンド &</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">裏で実行</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">次の操作</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">すぐできる</text></svg>"}'),

  ('linux-q59', 'ジョブ管理とシグナル',
   '`kill`コマンドは「プロセスを強制的に消す」専用のコマンドだと思われがちだが、実際にやっていることの正体として最も適切なものはどれか。',
   NULL::text,
   '["指定したプロセスに、番号で決まった合図（シグナル）を送る", "プロセスが使っていたメモリをOSに強制的に取り戻す", "プロセスのファイルをディスクから削除する", "プロセスをバックグラウンドからフォアグラウンドに戻す"]',
   0, '[0]', 'single',
   '{"asked": "killコマンドが実際にしていることの正体を問う問題。", "point": "killは「殺す」専用コマンドではなく、「合図を送る」コマンド。たまたまデフォルトの合図が終了を促すものなだけ。", "kid": "killという名前から「問答無用でプロセスを消す」コマンドだと思われがちだけど、実際には「このプロセスに、こういう合図（シグナル）を送ってね」という指示をするだけ。合図の種類によっては、終了以外の意味を持つものもある。", "eg": "たとえるなら、killは「相手に手紙を送る郵便屋さん」。手紙の中身（シグナルの種類）次第で「今すぐ帰ってきて」にも「一旦作業を止めて」にもなる。郵便屋さん自身が相手を消しているわけではない。", "terms": [["シグナル", "プロセスに送る番号付きの合図。SIGTERMやSIGKILLなど種類がある"], ["kill", "指定したプロセスにシグナルを送るコマンド"]], "think": "なぜ「削除」ではなく「合図」なのかがカギ。プロセスに直接手を突っ込んで強制終了させる操作は乱暴すぎる。代わりにOSは「合図を送るので、あとはプロセス自身の対応に任せる」という仕組みにした。多くのプロセスは合図を受け取ると自分で後片付けしてから終了するので、いきなり消すより安全。", "vs": "SIGKILLと混同しやすいが、SIGKILLは「合図を無視できない強制終了」という特殊なシグナルの1種であり、killコマンド自体は合図を送る仕組み全体を指す。", "opt": ["正解。killは指定したプロセスにシグナル（番号で決まった合図）を送るコマンドで、送る合図の種類は選べる。", "メモリを直接OSが取り戻すのはプロセス終了後の後処理であり、killコマンド自体がメモリ操作をしているわけではない。", "killはプロセスに合図を送るだけで、ディスク上のプログラムファイルを削除する操作は行わない。", "フォアグラウンドとバックグラウンドの切り替えはジョブ管理の別の操作（fgコマンドなど）であり、killの役割ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">killコマンドの正体</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">kill コマンド</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">合図を送る</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">シグナル</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">SIGTERM等</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">対象プロセス</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">合図に反応</text></svg>"}'),

  ('linux-q60', 'コンテナの正体',
   '「イメージ」と「コンテナ」はセットで語られるが、意味は別物。この2つの関係を最も適切に表しているものはどれか。',
   NULL::text,
   '["イメージは実行前の設計図、コンテナはそれを元に動いている実体", "イメージは動いている実体、コンテナは保存用の設計図", "イメージとコンテナは同じものの別の呼び方で、実体は1つしかない", "イメージはネットワーク設定、コンテナはディスク設定を指す言葉"]',
   0, '[0]', 'single',
   '{"asked": "イメージとコンテナの関係を問う問題。", "point": "イメージは「型」、コンテナは「型から作った動いている実体」。", "kid": "イメージは、必要なプログラムや設定を全部詰め込んだ「まだ動いていない設計図（型）」。コンテナは、そのイメージを元に実際に起動して、今動いている状態のもの。同じイメージから、コンテナはいくつでも作れる。", "eg": "たとえるなら、イメージは「クッキーの型」。コンテナは、その型を使って実際に焼いた「クッキー1枚1枚」。同じ型からクッキーは何枚でも焼ける（同じイメージから複数のコンテナを起動できる）。", "terms": [["イメージ", "動かす前の、プログラムと設定一式が入った型"], ["コンテナ", "イメージを元に実際に動いている実体"]], "think": "なぜこの区別が大事かがカギ。イメージ自体は「動いていない」ので、何度使い回しても壊れない。壊れたり止まったりするのは、あくまで起動した後のコンテナのほう。だからコンテナがおかしくなっても、同じイメージから作り直せば、まっさらな状態に戻せる。この「型は汚れない」という性質が、テスト環境を毎回同じ状態で再現できる理由になっている。", "vs": "VMのディスクイメージと混同しやすいが、コンテナのイメージはOS全体を含まない軽量な型で、そこがVMとの大きな違い（コンテナの正体カテゴリの他の問題を参照）。", "opt": ["正解。イメージは動く前の設計図、コンテナはそれを元に実際に動いている実体。", "実際の関係が逆になっている。動いているのはコンテナのほうで、イメージは動く前の型。", "イメージとコンテナは明確に別物で、同じイメージから複数のコンテナを作れる点からも実体は1つではない。", "イメージ・コンテナはどちらもネットワークやディスクの個別設定を指す言葉ではなく、もっと広く「実行の単位」を指す言葉。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">イメージからコンテナへ</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">イメージ</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">設計図(型)</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">起動</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">docker run等</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">コンテナ</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">動いている実体</text></svg>"}'),

  ('linux-q61', 'コンテナの正体',
   '1台のホストマシンで複数のコンテナを動かすと、それぞれのコンテナの中で`ps`のようなコマンドを打っても、自分のコンテナ以外のプロセスは見えない。この「見える範囲を分ける」仕組みの名前はどれか。',
   NULL::text,
   '["namespace（プロセスやネットワークなどの見える範囲を仕切る仕組み）", "cgroup（使えるCPUやメモリの量を制限する仕組み）", "ハイパーバイザー（仮想マシンのハードウェアを仮想化する仕組み）", "ファイアウォール（通信の通過を許可・拒否する仕組み）"]',
   0, '[0]', 'single',
   '{"asked": "コンテナごとにプロセスの見える範囲を分ける仕組みの名前を選ぶ問題。", "point": "「見える範囲を分ける」ならnamespace、「使える量を制限する」ならcgroup。", "kid": "同じホストマシンの中で複数のコンテナが動いていても、それぞれのコンテナからは自分以外のコンテナのプロセスが見えない。これは、ホストが持っているプロセスの一覧を、namespaceという仕組みでコンテナごとに「見える範囲」を仕切っているから。", "eg": "たとえるなら、1つの大きなオフィスビル（ホストマシン）の中に、間仕切り（namespace）で区切られた個室（コンテナ）がいくつもあるイメージ。同じビルの中にいても、隣の個室で誰が働いているかは見えない。", "terms": [["namespace", "プロセス・ネットワーク・ファイルシステムなどの「見える範囲」をコンテナごとに仕切る仕組み"], ["cgroup", "CPUやメモリなど「使える資源の量」を制限する仕組み。見える範囲ではなく使える量を制御する"]], "think": "なぜ見える範囲を分ける必要があるのかがカギ。もし全コンテナが互いのプロセスを見えたり操作できたりしたら、あるコンテナの不具合や攻撃が他のコンテナに簡単に波及してしまう。namespaceで見える範囲を仕切ることで、コンテナは「自分専用のマシンで動いているつもり」になれて、他のコンテナに干渉しにくくなる。", "vs": "cgroupと混同しやすいが、cgroupは「CPUを50%までしか使わせない」のような資源量の制限で、namespaceの「見える/見えない」の話とは役割が違う。両方があって初めて、コンテナは独立したプロセスの隔離になる。", "opt": ["正解。namespaceがプロセスなどの見える範囲をコンテナごとに仕切るので、他のコンテナのプロセスが見えない。", "cgroupは使えるCPUやメモリの量を制限する仕組みで、見える範囲を仕切る役割ではない。", "ハイパーバイザーはVM（仮想マシン）でハードウェアそのものを仮想化する仕組みで、コンテナはそもそもハイパーバイザーを使わない軽量な方式。", "ファイアウォールは通信の通過を制御する仕組みで、プロセスの一覧が見えるかどうかとは別の話。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">namespace vs cgroup</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">namespace</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">見える範囲を仕切る</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">他のプロセスが見えない</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">cgroup</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">使える量を制限する</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">CPU/メモリの上限</text></svg>"}'),

  ('linux-q62', 'ネットワークの基礎',
   '同じマシンで2つ目のWebサーバーを起動しようとしたら「ポートが既に使われています」というエラーが出た。この現象が起きる理由として最も適切なものはどれか。',
   NULL::text,
   '["1つのポート番号は、同時には1つのプロセスしか使えないから", "ポート番号はマシン全体で1つしか存在しないから", "ポート番号は1日に1回しか使えない決まりだから", "2つ目のプロセスがrootユーザーではなかったから"]',
   0, '[0]', 'single',
   '{"asked": "同じポート番号で2つのプロセスを起動しようとするとエラーになる理由を問う問題。", "point": "ポート番号は「その番号宛の通信を受け取る権利」を1プロセスが独占する切符。", "kid": "ポート番号は、マシンに届いた通信を「どのプログラムに渡すか」を決める番号札のようなもの。1つの番号札は同時に1つのプログラムしか持てない。すでに1つ目のWebサーバーがその番号を持っていると、2つ目は同じ番号を使おうとしても弾かれてしまう。", "eg": "たとえるなら、ポート番号は「郵便受けの番号」。同じ番号の郵便受けを2世帯が同時に使うと、届いた手紙をどちらに渡せばいいか分からなくなる。だからOSは1つの番号を1プロセスにしか割り当てない。", "terms": [["ポート", "通信を届ける先のプログラムを識別する番号"], ["ソケット", "プロセスとポートを結びつける通信の窓口"]], "think": "なぜ独占制なのかがカギ。もし2つのプロセスが同じポートで通信を受け取れてしまうと、届いた通信をどちらに渡すべきかOSが判断できなくなる。曖昧さを無くすため、OSは「1つのポートには1つのプロセスだけ」という規則を敷いている。だから2つ目を同じポートで起動しようとすると、OSがそれを拒否してエラーにする。", "vs": "IPアドレスと混同しやすいが、IPアドレスは「どのマシンか」を示す住所、ポートは「そのマシンの中のどのプログラムか」を示す番号で、役割の階層が違う。", "opt": ["正解。1つのポート番号は同時には1つのプロセスしか使えないため、既に使われているポートを2つ目のプロセスが使おうとするとエラーになる。", "1台のマシンには複数のポート番号（0〜65535番など）が存在し、1つしかないわけではない。", "ポート番号の利用に「1日1回まで」のような時間制限は無く、プロセスが使い終われば同じ番号をすぐ使い回せる。", "権限（rootかどうか）は一部の若い番号のポートに関わることはあるが、この「既に使われている」というエラーの直接の理由ではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ポートの独占</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"38\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">ポート8080</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">Webサーバー1が使用中</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">2つ目の起動</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">同じポートは使えない</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">エラーになる</text></svg>"}'),

  ('linux-q63', 'ネットワークの基礎',
   'テスト用のWebサーバーを起動したあと、ブラウザで `http://localhost:3000` や `http://127.0.0.1:3000` にアクセスして動作確認することがある。この `127.0.0.1`（localhost）が指しているものは何か。',
   NULL::text,
   '["今アクセスしている、自分自身のマシン", "インターネット上のどこかにある共有のテストサーバー", "ネットワークに繋がっていないことを示す特別な意味", "マシンの中で一番最初に起動したプロセス"]',
   0, '[0]', 'single',
   '{"asked": "127.0.0.1（localhost）が何を指しているかを問う問題。", "point": "127.0.0.1は「よそのマシンには出ていかず、自分自身に返ってくる」特別な住所。", "kid": "IPアドレスはマシンの住所のようなものだけど、`127.0.0.1`は特別な予約済みの住所で、「これを使う自分自身」を指す。だから、自分のマシンで動かしているWebサーバーに、自分のマシンから確認しにいくときに使われる。", "eg": "たとえるなら、127.0.0.1は「自分の家の中だけで通じる内線番号」のようなもの。外の郵便配達を使わず、家の中で自分から自分の部屋に声をかけているイメージ。", "terms": [["localhost", "自分自身を指す名前。127.0.0.1という住所と結びついている"], ["ループバックアドレス", "外に出ず自分自身に折り返す、127.0.0.1のようなアドレスの呼び方"]], "think": "なぜこの仕組みが必要かがカギ。テスト中のプログラムは、まだ外部に公開していないことが多い。それでも動作確認はしたい。そこで「ネットワークの外には出さず、自分自身の中だけで通信を折り返す」特別な住所を用意しておけば、外部に晒すことなく安全に自分のマシン上でアクセス確認ができる。", "vs": "普通のIPアドレス（他のマシンを指す住所）と混同しやすいが、127.0.0.1は「自分自身」に固定された特別な住所で、他のマシンからアクセスしても、そのマシン自身に返ってくるだけで意味を持たない。", "opt": ["正解。127.0.0.1（localhost）は、今アクセスしている自分自身のマシンを指す特別な予約済みアドレス。", "127.0.0.1は自分自身に折り返す住所であり、インターネット上の別のマシンを指す住所ではない。", "ネットワーク未接続を示す特別な意味を持つ住所は127.0.0.1とは別（例えば通信不能を示すエラーとは異なる）。", "127.0.0.1はプロセスの起動順とは無関係で、住所（ネットワークの宛先）を示すものであってプロセスの識別子ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">127.0.0.1のループバック</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">自分のマシン</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">リクエスト送信</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">127.0.0.1</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">外に出ない</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">自分のマシン</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">そのまま返る</text></svg>"}'),

  ('linux-q64', 'テキスト処理の基本',
   '`cat` コマンドは「ファイルの中身を表示するコマンド」として使われることが多いが、その正体として最も適切な説明はどれか。',
   NULL::text,
   '["ファイルの中身をそのまま標準出力に流すだけの単純なコマンド", "ファイルの中身を解析し、要約して表示するコマンド", "ファイルの中身を暗号化して保存し直すコマンド", "複数のファイルを1つに結合してディスクに保存するコマンド"]',
   0, '[0]', 'single',
   '{"asked": "catコマンドが実際にやっていることの正体を問う問題。", "point": "catは「concatenate（つなげる）」の略で、ファイルの中身をそのまま流すだけの単純な部品。", "kid": "catは、指定したファイルの中身をそのまま標準出力（普通は画面）に流すだけの、とてもシンプルなコマンド。要約もせず、加工もせず、そのまま垂れ流す。", "eg": "たとえるなら、catは「本のページをそのまま読み上げるだけの人」。内容を要約したり感想を言ったりはせず、書いてある通りにただ声に出すだけ。", "terms": [["cat", "concatenate（つなげる）の略。ファイルの中身をそのまま標準出力に流すコマンド"], ["標準出力", "コマンドの結果が流れ出ていく出口。普通は画面に表示される"]], "think": "なぜこんな単純なコマンドが重要なのかがカギ。catは単体では地味だが、標準出力にそのまま流すという性質のおかげで、パイプで他のコマンドに渡す入口として使いやすい。中身を加工しないからこそ、次のコマンド（grepなど）に「まっさらな中身」を渡せる。", "vs": "lessと混同しやすいが、lessは画面に収まる分だけ表示してスクロールできる「一部だけ見る」ツールで、catは全部を一気に流す点が違う。", "opt": ["正解。catはファイルの中身をそのまま標準出力に流すだけの単純なコマンド。", "catは中身を要約したり解析したりはせず、あるがままの中身を流すだけ。", "catは暗号化やファイルの書き換えは行わない。中身をそのまま表示（または流す）だけの読み取り用コマンド。", "catは複数ファイルを画面上でつなげて表示できるが、ディスクに保存するには別途リダイレクトの指定が必要で、それ自体が保存の主目的ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">catの正体</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ファイル</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">中身</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">cat</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">そのまま流す</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">標準出力</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">画面</text></svg>"}'),

  ('linux-q65', 'テキスト処理の基本',
   '何万行もある巨大なログファイルを`cat`で表示すると、画面が一瞬でスクロールしきってしまい何も読めない。この問題を解決するために使う、画面に収まる分だけ表示してスクロールできるコマンドはどれか。',
   NULL::text,
   '["less（1画面分ずつ表示し、スクロールして読み進められる）", "cat（ファイルの中身をそのまま全部流す）", "rm（ファイルを削除する）", "cp（ファイルを複製する）"]',
   0, '[0]', 'single',
   '{"asked": "巨大なファイルを画面に収まる分だけ表示するコマンドを選ぶ問題。", "point": "全部一気に見るのがcat、少しずつ読み進めるのがless。", "kid": "catは中身を全部一気に流すので、長いファイルだと画面が流れきってしまい、最初のほうが読めなくなる。lessは1画面分だけ表示して、そこで止まってくれる。矢印キーなどでスクロールしながら少しずつ読み進められる。", "eg": "たとえるなら、catは「本を1ページ目から最後まで一気に読み上げてしまう」やり方。lessは「1ページ読んだら止まって、めくっていいよと言うまで待ってくれる」やり方。長い本ほどlessのほうがありがたい。", "terms": [["less", "1画面分ずつ表示してスクロールできる、長いファイルを読むためのコマンド"], ["ページャ", "画面単位で区切って表示するツールの総称。lessはその代表格"]], "think": "なぜ「全部一気」と「少しずつ」の両方が必要かがカギ。短いファイルはcatで十分見渡せるが、長いファイルを全部流すと、読みたい箇所がすぐ画面外に流れてしまう。lessは画面という「窓」の大きさに合わせて表示を止めることで、大きなファイルでも自分のペースで読み進められるようにしている。", "vs": "catと混同しやすいが、catは加工せず全部流すだけで止まらない。lessは表示を1画面ずつに区切って止まってくれる点が違う（両方とも中身を変えずに読むだけという点は共通）。", "opt": ["正解。lessは1画面分ずつ表示し、スクロールしながら少しずつ読み進められるコマンド。", "catはファイルの中身を一気に全部流すコマンドで、長いファイルだと読みたい箇所がすぐ流れてしまう。", "rmはファイルを削除するコマンドで、中身を表示する用途とは正反対。", "cpはファイルを複製するコマンドで、中身を画面に表示する用途ではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">cat vs less</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">cat</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">全部を一気に流す</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">長いと読みにくい</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">less</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">1画面分ずつ表示</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">スクロールできる</text></svg>"}'),

  ('linux-q66', 'テキスト処理の基本',
   '大量の行が並んだログファイルの中から、「error」という文字列を含む行だけを取り出したい。このような「文字列で行を絞り込む」ことに特化したコマンドはどれか。',
   NULL::text,
   '["grep（指定した文字列を含む行だけを抜き出す）", "sort（行を並べ替える）", "wc（行数や文字数を数える）", "mkdir（ディレクトリを作る）"]',
   0, '[0]', 'single',
   '{"asked": "文字列を含む行だけを絞り込むコマンドを選ぶ問題。", "point": "「含む行だけ欲しい」ならgrep。並べ替えでも数えるでもなく絞り込み専門。", "kid": "grepは、渡された文字の並びの中から、指定した文字列を含む行だけを選んで表示してくれるコマンド。「errorを含む行だけちょうだい」というお願いを叶えてくれる係。", "eg": "たとえるなら、grepは「本の中から、特定の単語が出てくるページだけを付箋で残してくれる人」。関係ないページは飛ばして、その単語が出てくる行だけを見せてくれる。", "terms": [["grep", "指定した文字列（パターン）を含む行だけを抜き出すコマンド"], ["フィルタ", "入ってきたデータの一部だけを通す、絞り込みの役割をするプログラムの総称"]], "think": "なぜgrepのような専門コマンドが要るのかがカギ。もしgrepが無ければ、目視で全行を読んで探すしかない。grepは「文字列で行を絞り込む」という1つの仕事だけに特化しているので、他のコマンド（catやパイプ）と組み合わせやすく、大量の行から一瞬で目的の行だけを取り出せる。", "vs": "sortと混同しやすいが、sortは行の並び順を変えるだけで、行を減らしたり選んだりはしない。grepは「含むか含まないか」で行を選び出す点が違う。", "opt": ["正解。grepは指定した文字列を含む行だけを抜き出す、絞り込み専門のコマンド。", "sortは行を並べ替えるコマンドで、特定の文字列を含む行だけを選び出す機能ではない。", "wcは行数・単語数・文字数を数えるコマンドで、行の中身を絞り込む機能ではない。", "mkdirはディレクトリを新しく作るコマンドで、テキストの中身とは無関係。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">grepの絞り込み</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">全行</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1000行</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">grep error</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">含む行だけ</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">結果</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">数行だけ</text></svg>"}'),

  ('linux-q67', 'テキスト処理の基本',
   '「ログファイルを`cat`で流して、その結果を`grep`で絞り込み、さらに`less`でゆっくり読む」というふうに、`|`（パイプ）でコマンドを何個もつなげて使うことがある。この使い方の考え方として最も適切なものはどれか。',
   NULL::text,
   '["1つのことしかできない単純な部品を、パイプでつなげて複雑な作業を組み立てる", "パイプでつなぐと、すべてのコマンドが同時に並列で実行される", "パイプは見た目を整えるための記号で、機能的な意味は持たない", "パイプでつなげるほど、それぞれのコマンドの機能が増えていく"]',
   0, '[0]', 'single',
   '{"asked": "cat|grep|lessのように何個もパイプでつなぐ使い方の考え方を問う問題。", "point": "1つ1つは単純な部品を、パイプで組み立てて複雑な仕事をする、がLinuxらしい発想。", "kid": "catもgrepもlessも、それぞれ1つのことしかしない単純なコマンド。でもパイプでつなげると、「流す→絞り込む→ゆっくり読む」という一連の作業を、1行で組み立てられる。それぞれの部品は変わらず単純なまま。", "eg": "たとえるなら、レゴブロックの1個1個は単純な形だけど、組み合わせると複雑な建物が作れるのと同じ。catやgrepという単純なブロックを、パイプで繋いで自分だけの作業の流れを作る。", "terms": [["パイプ(|)", "前のコマンドの出力を、次のコマンドの入力にそのままつなぐ記号"], ["Unix哲学", "1つのことをうまくやる小さいプログラムを、組み合わせて使うという設計の考え方"]], "think": "なぜ小さい部品を組み合わせる設計にしたのかがカギ。もし「ログを流して絞り込んでゆっくり読む」という機能を1つの巨大なコマンドにまとめてしまうと、少し違う組み合わせをしたいたびに新しいコマンドが必要になる。単純な部品のままパイプでつなぐ方式なら、部品の組み合わせを変えるだけで無限に違う作業を作れる。これがUnix哲学の実践。", "vs": "「1つの万能コマンドで全部やる」発想と混同しやすいが、Linuxの流儀は逆で、あえて機能を小さく保ったまま組み合わせの自由度で複雑さに対応する。", "opt": ["正解。1つのことしかできない単純な部品を、パイプでつなげて複雑な作業を組み立てるのがLinuxらしい発想。", "パイプでつないだコマンドは、前のコマンドの出力が次のコマンドの入力になる順番の関係にあり、無条件に同時並列で動くわけではない。", "パイプは前後のコマンドの出力と入力を実際につなぐ機能を持ち、単なる見た目の記号ではない。", "パイプでつなげても、それぞれのコマンド自体の機能（catはcat、grepはgrep）が増えるわけではなく、組み合わせの幅が増えるだけ。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">小さい部品を組み合わせる</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">cat</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">流す</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">grep</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">絞り込む</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">less</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ゆっくり読む</text></svg>"}'),

  ('linux-q68', 'テキスト処理の基本',
   'もし`grep`が「文字列を含む行を探す」機能に加えて「ファイルの削除」「メール送信」まで一緒にできる巨大なコマンドだったら、テキスト処理の組み立てにどんな影響が出ると考えられるか。',
   NULL::text,
   '["機能が絡み合い、他のコマンドと自由に組み合わせて使うことが難しくなる", "処理速度が上がり、パイプでの組み合わせがより自由になる", "grep単体の使い方が今より簡単になり、覚えることが減る", "特に何も変わらず、今のgrepと同じように使える"]',
   0, '[0]', 'single',
   '{"asked": "grepが機能を詰め込んだ巨大なコマンドだったらどうなるかを問う問題。", "point": "機能を欲張ると、組み合わせの自由度は逆に下がる。", "kid": "grepが「絞り込み」だけをやる単純なコマンドだからこそ、「絞り込んだ結果を別のコマンドに渡す」というパイプでの組み合わせが自然にできる。もし削除やメール送信まで一緒にやる巨大なコマンドだったら、絞り込みだけしたいときにも余計な機能がついてきてしまい、他のコマンドと組み合わせて使うのがかえって難しくなる。", "eg": "たとえるなら、grepが「文字列を探すことしかしない虫めがね」だから、他の道具（ハサミやのり）と自由に組み合わせられる。もし虫めがねに「切る」「貼る」まで機能が詰め込まれていたら、単純に「探すだけ」使いたいときに使いにくくなる。", "terms": [["単一責任", "1つの部品には1つの役割だけを持たせるという考え方"], ["Unix哲学", "1つのことをうまくやる小さいプログラムを組み合わせて使う設計の考え方"]], "think": "なぜ機能を絞ることが良い設計なのかがカギ。機能を1つに絞れば、そのコマンドが「何をするか」が明確になり、他のコマンドと安心して組み合わせられる。機能を詰め込むと、意図しない副作用（絞り込みたいだけなのにメールが送られる、など）が起きるリスクが増え、パイプでの自由な組み立てがかえって難しくなる。", "vs": "「機能が多いほど便利」という直感と混同しやすいが、Unix哲学ではむしろ機能を絞ることで、組み合わせの自由度という別の便利さを得ている。", "opt": ["正解。機能が絡み合うと、その部品を他のコマンドと自由に組み合わせて使うことが難しくなる。", "機能を詰め込んでも処理速度が上がるとは限らず、むしろ組み合わせの自由度は下がる方向に働く。", "機能が増えるほど、覚えることや気をつけるべき副作用は増える方向に働き、単純にはならない。", "機能を詰め込めば、単純な絞り込み専用だったころとは使い勝手が変わり、何も変わらないとは言えない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">単機能 vs 多機能</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">grep(単機能)</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">絞り込みだけ</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">他と自由に組合せ</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">巨大grep(仮)</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">削除やメールも実行</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">組合せづらい</text></svg>"}'),

  ('linux-q69', 'テキスト処理の基本',
   'grepでは「error」のような固定の文字列だけでなく、「数字が3つ並んでいる部分」のような柔軟なパターンでも行を探せる。この「パターンで探す」仕組みを何と呼ぶか。',
   NULL::text,
   '["正規表現（文字の並び方のルールを使って探すパターン）", "シバン（このファイルをどのプログラムで実行するか指定する目印）", "環境変数（プロセス間で共有される値の入れ物）", "シンボリックリンク（別のファイルを指し示す特殊なファイル）"]',
   0, '[0]', 'single',
   '{"asked": "「パターンで探す」仕組みの名前を問う問題。", "point": "決まった文字列だけでなく「並び方のルール」で探すのが正規表現。", "kid": "「error」のような決まった文字列だけでなく、「数字が3つ並んでいる」「英字で始まる」のような、文字の並び方のルールを指定して探す方法がある。このルールの書き方を正規表現と呼ぶ。grepはこの正規表現を使って、より柔軟に行を絞り込める。", "eg": "たとえるなら、固定の文字列で探すのは「『山田太郎』という名前をそのまま探す」やり方。正規表現で探すのは「『山田』で始まって、その後に漢字が2文字続く名前を全部探す」というふうに、形のルールで探すやり方。", "terms": [["正規表現", "文字の並び方のルール（パターン）を使って文字列を探す仕組み"], ["パターンマッチング", "決まった文字列ではなく、ルールに合う部分を探すこと"]], "think": "なぜパターンで探す仕組みが要るのかがカギ。ログの中の「エラーコードの数字」は毎回違う数字なので、固定の文字列では探せない。正規表現を使えば「数字が並んでいる部分」のような形のルールで探せるので、毎回違う具体的な値でも同じルールで一括して見つけられる。この本ドリルでは構文そのものの暗記はせず、「パターンで探せる」という発想だけ押さえれば十分。", "vs": "固定の文字列検索と混同しやすいが、固定の文字列検索は「これと完全に一致する部分」だけを探すのに対し、正規表現は「このルールに当てはまる部分」という柔軟な探し方ができる点が違う。", "opt": ["正解。正規表現は文字の並び方のルールを使って、柔軟なパターンで文字列を探す仕組み。", "シバンはスクリプトの実行方法を指定する目印で、テキストの中からパターンを探す仕組みとは無関係。", "環境変数はプロセス間で値を共有する仕組みで、テキストのパターン検索とは無関係。", "シンボリックリンクは別のファイルを指し示す特殊なファイルで、テキストのパターン検索とは無関係。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">固定文字列 vs パターン</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">\"error\"</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">固定の文字列</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">正規表現</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">並び方のルール</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">柔軟に一致</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">様々な値</text></svg>"}'),

  ('linux-q70', 'テキスト処理の基本',
   'コマンドの結果を「次のコマンドに渡したい」ときは`|`（パイプ）を使い、「ファイルに保存しておきたい」ときは`>`（リダイレクト）を使う。この2つの記号の役割の違いとして最も適切なものはどれか。',
   NULL::text,
   '["パイプは次のコマンドの入力へ、リダイレクトはファイルへ出力をつなぐ", "パイプはファイルへ、リダイレクトは次のコマンドへ出力をつなぐ", "パイプとリダイレクトはまったく同じ働きをする、書き方が違うだけの記号", "パイプは入力を受け取る記号で、出力には一切関与しない"]',
   0, '[0]', 'single',
   '{"asked": "パイプとリダイレクトの役割の違いを問う問題。", "point": "行き先が「次のプログラム」ならパイプ、「ファイル」ならリダイレクト。", "kid": "パイプ`|`は、あるコマンドの出力を、次のコマンドの入力としてそのまま渡す記号。リダイレクト`>`は、コマンドの出力をファイルとして保存する記号。どちらも「出力をどこかに送る」点は同じだけど、送り先が「次のプログラム」か「ファイル」かが違う。", "eg": "たとえるなら、パイプは「できた料理をそのまま次の人（次のコマンド）に手渡す」やり方。リダイレクトは「できた料理をタッパー（ファイル）に詰めて保存しておく」やり方。どちらも料理（出力）を運ぶ点は同じだけど、行き先が違う。", "terms": [["パイプ(|)", "出力を次のコマンドの入力につなぐ記号"], ["リダイレクト(>)", "出力をファイルに保存する記号"]], "think": "なぜ2つの記号を使い分けるのかがカギ。出力の使い道が「すぐ次の処理に使いたい」のか「あとで見返せるように残しておきたい」のかで、行き先を変える必要がある。パイプは一時的にプログラム同士をつなぐ配管、リダイレクトは結果を長期保存する容器、という役割分担になっている。", "vs": "似た見た目の記号のせいで混同しやすいが、パイプの先には「プログラム」、リダイレクトの先には「ファイル」が来るという行き先の違いで覚える。", "opt": ["正解。パイプは出力を次のコマンドの入力へ、リダイレクトは出力をファイルへつなぐ。", "パイプとリダイレクトの行き先が入れ替わっており、説明が逆になっている。", "パイプとリダイレクトは行き先（次のプログラムかファイルか）が明確に違い、同じ働きではない。", "パイプは前のコマンドの出力を次のコマンドの入力として渡す、出力にも入力にも関わる記号で、出力に関与しないという説明は誤り。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">パイプ vs リダイレクト</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">| パイプ</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">次のコマンドへ</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">その場で処理を継続</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">> リダイレクト</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">ファイルへ保存</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">後から見返せる</text></svg>"}'),

  ('linux-q71', 'パッケージ管理の考え方',
   '新しいソフトを使いたいとき、公式サイトから毎回ソースコードをダウンロードしてビルドするのではなく、パッケージマネージャで「インストール」する。パッケージマネージャが解決してくれる一番の問題は何か。',
   NULL::text,
   '["必要な部品（依存関係）集めやビルド手順を毎回自分でやらずに済む", "ソフトの機能自体を自動的に増やしてくれる", "インターネット回線の速度を自動的に上げてくれる", "ソフトのバグを自動的にすべて修正してくれる"]',
   0, '[0]', 'single',
   '{"asked": "パッケージマネージャが解決してくれる一番の問題を問う問題。", "point": "パッケージマネージャの価値は「面倒な準備作業をまとめて肩代わりしてくれる」こと。", "kid": "ソフトを動かすには、そのソフト本体だけでなく、一緒に必要な部品（依存関係）や、正しい組み立て手順（ビルド）が要ることが多い。パッケージマネージャは、この「必要な部品を集めて、正しい手順で組み立てる」という面倒な作業をまとめて代わりにやってくれる。", "eg": "たとえるなら、パッケージマネージャは「家具の完成品を届けてくれる通販」。自分で木材を集めてネジを買って組み立てる（ソースからビルドする）代わりに、必要な部品が全部揃った状態ですぐ使える形で届けてくれる。", "terms": [["パッケージ", "インストールに必要な情報をひとまとめにした配布用の単位"], ["依存関係", "あるソフトを動かすために一緒に必要になる、別のソフトや部品"], ["ビルド", "ソースコードを実際に動くプログラムに組み立てる作業"]], "think": "なぜソースからのビルドが面倒なのかがカギ。1つのソフトが動くには、他の何十個ものライブラリが正しいバージョンで揃っている必要があることが多い。手作業だと、足りない部品を1個ずつ探してビルドする羽目になる。パッケージマネージャは「このソフトにはこれとこれが要る」という情報をあらかじめ持っていて、必要な部品を自動でまとめて揃えてくれる。", "vs": "「ソフト自体の機能を増やす」ことと混同しやすいが、パッケージマネージャが増やすのはあくまで「インストールの手間の少なさ」であって、ソフト自体の機能を作り足すわけではない。", "opt": ["正解。パッケージマネージャは、必要な部品集めやビルド手順といった面倒な準備作業を肩代わりしてくれる。", "パッケージマネージャはインストールを助ける仕組みで、ソフト自体の機能を増やすものではない。", "パッケージマネージャはインターネット回線の速度とは無関係で、通信速度を上げる機能は持たない。", "パッケージマネージャはインストールを楽にするための仕組みで、ソフトのバグを自動修正する機能ではない（アップデートで直ることはあっても、自動修正そのものではない）。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">手作業 vs パッケージ管理</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">部品集め</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">手作業だと大変</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">パッケージ管理</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">自動で解決</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">すぐ使える</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">完成形</text></svg>"}'),

  ('linux-q72', 'パッケージ管理の考え方',
   'あるソフトAをインストールしようとしたら、「ソフトBも必要です」と言われ、Bをインストールしようとしたら「ソフトCも必要です」と芋づる式に要求されることがある。この「一緒に必要になる別のソフト」の関係を何と呼ぶか。',
   NULL::text,
   '["依存関係（あるソフトを動かすために一緒に必要になる関係）", "対称関係（互いに同じ立場で影響し合う関係）", "継承関係（あるプログラムの機能を別のプログラムが引き継ぐ関係）", "排他関係（同時には両方使えない関係）"]',
   0, '[0]', 'single',
   '{"asked": "「一緒に必要になる別のソフト」の関係を指す言葉を問う問題。", "point": "「AがBを必要とする」という一方向のつながりが依存関係。", "kid": "多くのソフトは、自分だけでは動けず、部品として別の小さいソフト（ライブラリ）を借りて動いている。「AはBが無いと動けない」という、この一方向のつながりを依存関係と呼ぶ。依存先のBがさらに別のCに依存していることもあり、芋づる式につながっていく。", "eg": "たとえるなら、料理（ソフトA）を作るのに、特定の調味料（ソフトB）が必要で、その調味料を作るのにさらに別の原材料（ソフトC）が必要、というふうに材料が連鎖しているイメージ。", "terms": [["依存関係", "あるソフトを動かすために、一緒に必要になる別のソフトとの関係"], ["依存関係の解決", "必要な依存先を自動的に探し出して揃えること"]], "think": "なぜ依存関係が芋づる式になるのかがカギ。多くのソフトは、車輪の再発明を避けるために、既にある便利な部品（ライブラリ）を借りて作られている。借りた部品がさらに別の部品を借りていることも珍しくない。パッケージマネージャは、この依存関係のつながりを丸ごと自動でたどって、必要なものを全部揃えてくれる（これが依存関係の解決）。", "vs": "継承関係と混同しやすいが、継承は「機能を引き継ぐ」プログラミング上の設計の話で、依存関係は「動かすために必要とする」パッケージ同士の関係を指す、別のレベルの話。", "opt": ["正解。依存関係は、あるソフトを動かすために一緒に必要になる別のソフトとの関係を指す。", "対称関係のような「互いに同じ立場」という意味の言葉ではなく、依存関係は「AがBを必要とする」という一方向のつながり。", "継承関係はプログラムの設計上の概念で、パッケージ同士の「一緒に必要になる」という関係を指す言葉ではない。", "排他関係は「同時に両方は使えない」という意味の言葉で、依存関係とは逆に近い性質。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">依存関係の連鎖</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ソフトA</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">欲しいもの</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ソフトB</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Aが必要</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ソフトC</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">Bが必要</text></svg>"}'),

  ('linux-q73', 'パッケージ管理の考え方',
   'パッケージマネージャは「このパッケージが欲しい」と頼むと、インターネット上のどこかからそのパッケージを見つけてダウンロードしてくれる。このパッケージがまとめて置かれている「倉庫」にあたる場所を何と呼ぶか。',
   NULL::text,
   '["リポジトリ（パッケージがまとめて置かれている配布元）", "キャッシュ（一度使ったデータを一時的に保存しておく場所）", "スワップ（メモリが足りないときにディスクを代用する仕組み）", "シンボリックリンク（別のファイルを指し示す特殊なファイル）"]',
   0, '[0]', 'single',
   '{"asked": "パッケージがまとめて置かれている「倉庫」にあたる場所の名前を問う問題。", "point": "パッケージの置き場所（配布元）を指す言葉がリポジトリ。", "kid": "パッケージマネージャは、自分のマシンの外にある「パッケージの倉庫」から必要なものを取り寄せている。この倉庫にあたる場所をリポジトリと呼ぶ。リポジトリには、たくさんのパッケージが整理されて置かれている。", "eg": "たとえるなら、リポジトリは「通販サイトの倉庫」。パッケージマネージャは、そこから欲しい商品（パッケージ）を注文して届けてもらう役目を持つ、通販サイトの窓口のようなもの。", "terms": [["リポジトリ", "パッケージがまとめて置かれている配布元の場所"], ["パッケージマネージャ", "リポジトリからパッケージを探し、依存関係も含めて取り寄せてインストールする係"]], "think": "なぜリポジトリという「集約された置き場」が必要かがカギ。もしパッケージがあちこちのサイトにバラバラに散らばっていたら、どこにあるか探すだけで一苦労になる。リポジトリという1つの信頼できる置き場に集約しておくことで、パッケージマネージャは「ここを探せば必ず見つかる」という前提で自動的に取り寄せられる。", "vs": "キャッシュと混同しやすいが、キャッシュは「一度取り寄せたものを手元に一時保存しておく場所」で、リポジトリは「そもそもの取り寄せ元（倉庫そのもの）」という違いがある。", "opt": ["正解。リポジトリはパッケージがまとめて置かれている、パッケージマネージャの配布元にあたる場所。", "キャッシュは一度使ったデータを一時的に手元に残しておく仕組みで、パッケージの配布元そのものではない。", "スワップはメモリ不足を補うためにディスクを代用する仕組みで、パッケージの配布元とは無関係。", "シンボリックリンクは別のファイルを指し示す特殊なファイルの仕組みで、パッケージの配布元とは無関係。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">リポジトリから取り寄せる</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">リポジトリ</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">パッケージの倉庫</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">パッケージ管理</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">検索・取得</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">自分のマシン</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">インストール完了</text></svg>"}'),

  ('linux-q74', 'パッケージ管理の考え方',
   'パッケージマネージャでインストールしたソフトは、アンインストールコマンド一発できれいに消せることが多い。手動でファイルをコピーして入れたソフトより後片付けがしやすい理由として最も適切なものはどれか。',
   NULL::text,
   '["どのファイルをどこに置いたか、パッケージマネージャが記録として管理しているから", "パッケージマネージャでインストールしたソフトは、ファイルを1つも作らないから", "手動でコピーしたソフトのほうが、実は消しやすい仕組みになっているから", "アンインストールコマンドは、関係のない別のソフトも道連れで全部消すから"]',
   0, '[0]', 'single',
   '{"asked": "パッケージマネージャ経由のアンインストールがきれいにできる理由を問う問題。", "point": "「配置した記録が残っている」から、後片付けも正確にできる。", "kid": "パッケージマネージャは、インストールするときに「どのファイルをどこに置いたか」を自分の記録（データベース）に残している。だからアンインストールするときも、その記録を見返して「置いたファイルだけ」を正確に消せる。手動でコピーしたソフトには、こういう記録が無いので、どこに何を置いたか忘れがちで消し残しが起きやすい。", "eg": "たとえるなら、パッケージマネージャは「荷物を運んだ配送業者が、置いた場所を全部台帳に記録している」ようなもの。回収を頼めば、台帳を見てちゃんと全部回収してくれる。手動コピーは台帳の無い自己判断の引っ越しなので、荷物の置き場所を忘れやすい。", "terms": [["パッケージデータベース", "どのパッケージのどのファイルをどこに置いたかを記録している、パッケージマネージャ内部の台帳"], ["アンインストール", "インストールしたファイル一式を正確に取り除く操作"]], "think": "なぜ記録が無いときれいに消せないのかがカギ。手動コピーでソフトを入れると、「どのファイルがそのソフト由来か」を人間の記憶に頼るしかなく、時間が経つと忘れてしまう。パッケージマネージャは配置した瞬間から記録を残しているので、後からでも正確に「これはこのソフトの一部だった」とたどれる。この記録の有無が、後片付けのしやすさの差になる。", "vs": "「アンインストールコマンドが特別な魔法を使っている」という誤解に注意。実際には特別な魔法ではなく、単に「事前の記録を正確に読み返しているだけ」というのが正体。", "opt": ["正解。パッケージマネージャはどのファイルをどこに置いたか記録として管理しているため、アンインストール時に正確に消せる。", "パッケージマネージャでインストールしても、実際には設定ファイルやプログラム本体などのファイルは作られている。", "手動でコピーしたソフトには配置の記録が残らないことが多く、パッケージマネージャ経由より後片付けが難しくなりやすい。", "アンインストールは記録されたそのパッケージのファイルだけを対象にするのが基本で、無関係な別のソフトを道連れにする動作ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">記録があるから正確に消せる</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">インストール時</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">配置を記録</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">アンインストール</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">記録を参照</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">正確に削除</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">消し残しなし</text></svg>"}'),

  ('linux-q75', 'パッケージ管理の考え方',
   '「パッケージマネージャでインストールする」方法と「ソースコードを取ってきて自分でビルドする」方法を比べたとき、パッケージマネージャを使う一番の利点として適切なものはどれか。',
   NULL::text,
   '["依存関係の解決やビルド済みの状態がすでに用意されており、手間が少ない", "ソースからビルドする方法より、常に新しいバージョンが手に入る", "ソースからビルドしたソフトは、パッケージマネージャでは絶対に管理できない", "パッケージマネージャを使うと、ソースコードの中身が自動的に読みやすくなる"]',
   0, '[0]', 'single',
   '{"asked": "パッケージマネージャとソースからのビルドを比べたときの利点を問う問題。", "point": "パッケージマネージャの利点は「もう組み立て済みのものが届く」手間の少なさ。", "kid": "ソースからビルドする方法は、必要な部品を自分で集めて、正しい手順で組み立てる必要がある。パッケージマネージャは、その組み立てをあらかじめ誰かがやってくれた「完成品（ビルド済み）」を配っているので、依存関係もビルドの手間も気にせず、すぐ使える状態で手に入る。", "eg": "たとえるなら、ソースからビルドは「材料を買って一から料理する」やり方。パッケージマネージャは「できあがった料理を注文する」やり方。どちらも同じ料理にたどり着けるが、かかる手間がまったく違う。", "terms": [["ビルド済みパッケージ", "あらかじめ組み立て・コンパイルが済んだ状態で配布されるパッケージ"], ["ソースからのビルド", "ソースコードを自分の環境でコンパイルして、動くプログラムに組み立てること"]], "think": "なぜ手間の差が生まれるのかがカギ。ソースコードは「材料」であって、そのままでは動かせない。動かすには、依存関係を集め、正しい手順でコンパイルする必要があり、環境によってはうまくいかないことも多い。パッケージマネージャは、この面倒な組み立て作業を代わりに済ませた状態のものを配っているので、利用者は「届いたらすぐ使う」だけで済む。", "vs": "「新しいバージョンが手に入る」という誤解に注意。実際にはソースから最新版を直接ビルドしたほうが最新の変更を早く反映できることもあり、パッケージマネージャの配布物は少し遅れて追従することが多い。", "opt": ["正解。パッケージマネージャは依存関係の解決やビルド済みの状態がすでに用意されており、手間が少ない。", "パッケージマネージャの配布物は、リポジトリへの反映に時間がかかることがあり、ソースから直接ビルドするより新しいとは限らない。", "ソースからビルドしたソフトも、自分でパッケージ化する仕組みを使えば管理対象にできることがあり、「絶対に管理できない」は言い過ぎ。", "パッケージマネージャはインストールを助ける仕組みであり、ソースコードの中身の読みやすさ自体を変える機能ではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ソースからビルド vs パッケージ管理</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">ソースからビルド</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">材料集め</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">自分で組み立て</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">パッケージ管理</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">完成品を取得</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">すぐ使える</text></svg>"}'),

  ('linux-q76', 'パッケージ管理の考え方',
   'あるパッケージを最新版にアップデートしたとき、そのパッケージが依存している別のパッケージも、必要なら一緒に新しいバージョンへ更新される。この仕組みが無かったら起こりうる困った事態として最も適切なものはどれか。',
   NULL::text,
   '["新しい版が古い依存パッケージと噛み合わず、正しく動かなくなる恐れがある", "パッケージのサイズが常に増え続けてディスクがすぐいっぱいになる", "依存関係という考え方自体が成立しなくなる", "アップデートする度に必ずパスワードの再設定が必要になる"]',
   0, '[0]', 'single',
   '{"asked": "依存関係も含めたアップデートが無かった場合に起こりうる問題を問う問題。", "point": "バージョン同士の「噛み合わせ」まで面倒を見てくれるのが、依存関係込みのアップデート。", "kid": "あるソフトを新しいバージョンにすると、そのソフトが必要とする部品（依存先）も、新しいバージョンに対応したものでないと正しく動かないことがある。パッケージマネージャは、アップデートのときにこの「組み合わせの噛み合わせ」まで考えて、必要な依存先も一緒に更新してくれる。", "eg": "たとえるなら、スマホ本体を最新OSにアップデートしたのに、アプリだけ古いままだと、うまく動かなくなることがあるのと同じ。本体とアプリのバージョンの噛み合わせが大事なように、ソフトとその依存先のバージョンの噛み合わせも大事。", "terms": [["バージョンの整合性", "組み合わせて使うソフト同士のバージョンが噛み合っている状態"], ["依存関係の解決", "必要な依存先を、正しいバージョンも含めて自動的に揃えること"]], "think": "なぜ噛み合わせが崩れると困るのかがカギ。ソフトは、依存先が「このバージョン以上」であることを前提に作られていることが多い。依存先だけ古いままだと、新しいソフトが期待する機能が依存先に無く、正しく動かない・エラーになるといった不具合が起きる。パッケージマネージャが依存関係も含めてアップデートしてくれることで、この噛み合わせのズレを利用者が意識しなくて済む。", "vs": "「アップデートすれば依存関係という考え方自体が要らなくなる」という誤解に注意。アップデートで解決されるのはバージョンの噛み合わせであり、依存関係という関係性そのものは常に存在し続ける。", "opt": ["正解。依存関係も含めたアップデートが無いと、新しい版が古い依存パッケージと噛み合わず正しく動かなくなる恐れがある。", "アップデートの仕組みとディスク容量の増加ペースは直接結びついた話ではなく、この問題の中心的な困りごとではない。", "アップデートが行われても、依存関係という「一緒に必要になる」という関係性自体は無くならない。", "アップデートのたびにパスワードの再設定が必須になるという仕組みではなく、この問題とは無関係。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">依存関係込みのアップデート</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ソフトA更新</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">新バージョン</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">依存先Bも確認</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">噛み合うか</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">Bも更新</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">整合性を保つ</text></svg>"}'),

  ('linux-q77', 'シェルスクリプトの入り口',
   'シェルスクリプトのファイルの1行目に `#!/bin/bash` のような行を書くことがある。この行（シバン）の役割として最も適切なものはどれか。',
   NULL::text,
   '["このファイルをどのプログラムに実行させるかを指定する目印", "このファイルをコメントとして無視させるための記号", "このファイルの文字コードを指定するための記号", "このファイルの実行権限を自動的に付与する記号"]',
   0, '[0]', 'single',
   '{"asked": "シバン（#!から始まる1行目）の役割を問う問題。", "point": "シバンは「このファイルは、この解釈者に読ませてね」という宛先指定。", "kid": "シェルスクリプトは、ただのテキストファイルに過ぎない。そのままでは「誰がこの中身を読んで実行すればいいか」が分からない。1行目にシバンを書いておくと、「このファイルはbashというプログラムに読ませて実行してね」とOSに伝えられる。", "eg": "たとえるなら、シバンは手紙の宛名書きのようなもの。中身（本文）がどんなに正しくても、宛名（どのプログラムが読むべきか）が書いていないと、誰に渡せばいいか分からず届かない。", "terms": [["シバン(#!)", "ファイルの1行目に書く、実行するプログラムを指定する目印"], ["インタプリタ", "スクリプトの中身を1行ずつ読んで実行するプログラム。bashやpythonなど"]], "think": "なぜOSはシバンを見る必要があるのかがカギ。プログラムのファイルには、機械語で書かれた実行ファイルと、テキストで書かれたスクリプトの2種類がある。テキストのスクリプトは、それ単体では動けず、誰か（インタプリタ）に読んでもらう必要がある。シバンを見ることで、OSは「このファイルはbashに渡して実行すればいい」と正しく判断できる。", "vs": "コメント記号`#`と混同しやすいが、シバンは`#!`という特別な2文字の組み合わせで、ファイルの1行目に限り「実行するプログラムの指定」という特別な意味を持つ。2行目以降の`#`は普通のコメントのまま。", "opt": ["正解。シバンは、このファイルをどのプログラムに実行させるかを指定する目印。", "シバンは特別な意味を持つ1行目の記号で、ファイル全体をコメントとして無視させる効果はない。", "シバンは実行するプログラムを指定する仕組みで、文字コードの指定を主目的とした記号ではない。", "シバンを書いただけでは実行権限は付与されず、権限はchmodなど別の操作で与える必要がある。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">シバンの役割</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">#!/bin/bash</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1行目の宛名</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">OSが読む</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">実行プログラムを判断</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">bashが実行</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">中身を処理</text></svg>"}'),

  ('linux-q78', 'シェルスクリプトの入り口',
   '毎日ターミナルで同じコマンドを3つ順番に打っている作業がある。これをシェルスクリプトにまとめる、という発想の本質として最も適切なものはどれか。',
   NULL::text,
   '["普段手で打つコマンドの並びを、そのままファイルに書き出して自動化する", "コマンドをシェルスクリプトにすると、実行速度が機械語並みに速くなる", "シェルスクリプトにすると、コマンドの意味が変わり別の動作になる", "シェルスクリプトはシェルとはまったく別の、独立した専用のプログラム言語である"]',
   0, '[0]', 'single',
   '{"asked": "シェルスクリプトにまとめるという発想の本質を問う問題。", "point": "シェルスクリプトの正体は「普段打っているコマンドの台本」。", "kid": "シェルスクリプトは、普段ターミナルで1つずつ手で打っているコマンドを、そのままファイルに書き出しただけのもの。ファイルを実行すれば、書いてある順番通りにコマンドが自動で実行されていく。", "eg": "たとえるなら、シェルスクリプトは「毎朝やる準備の手順を書いたメモ」。メモを見ながら1つずつやる代わりに、そのメモをロボットに渡せば、書いてある通りに自動でやってくれるイメージ。", "terms": [["シェルスクリプト", "コマンドを順番に並べて書いた、自動実行できるファイル"], ["自動化", "手作業で繰り返していたことを、プログラムに任せること"]], "think": "なぜ手で打つ延長線上として理解するのが大事かがカギ。シェルスクリプトを、まったく別の難しい専用言語だと思うとハードルが上がる。実際は「普段打っているコマンドを、そのまま順番に並べただけ」という延長線上にある。だから、まず手でコマンドを打って動作確認し、それをそのままファイルにコピーするところから始められる。", "vs": "「シェルスクリプトはシェルとは別物」という誤解に注意。シェルスクリプトは、シェル自身がそのまま読んで実行できる、普段の対話的な入力と地続きのもの。", "opt": ["正解。シェルスクリプトは、普段手で打つコマンドの並びをそのままファイルに書き出して自動化したもの。", "シェルスクリプトはコマンドを順番に呼び出す仕組みであり、機械語のような高速な実行に変わるわけではない。", "ファイルに書き出しても、コマンド1つ1つの意味や動作自体は普段手で打つときと変わらない。", "シェルスクリプトは、普段使っているシェル自身が読んで実行するものであり、シェルとまったく別の独立した言語ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">手打ちからスクリプトへ</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">手で1個ずつ打つ</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">毎日繰り返す</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ファイルに書く</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">順番を保存</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">実行</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">自動で全部</text></svg>"}'),

  ('linux-q79', 'シェルスクリプトの入り口',
   'シェルスクリプトの中で `name="suzuki"` のように書き、その後 `$name` として使い回すことがある。この「値に名前を付けて使い回す」仕組みの役割として最も適切なものはどれか。',
   NULL::text,
   '["同じ値を何度も書き直さずに、名前を通して繰り返し利用できるようにする", "変数を使うと、スクリプトの実行速度が2倍になる", "変数はシェルスクリプトの中でしか存在せず、コマンドの引数には渡せない", "変数を使うことで、コマンドの実行権限が自動的に上がる"]',
   0, '[0]', 'single',
   '{"asked": "シェルスクリプトにおける変数の役割を問う問題。", "point": "変数は「同じ値の使い回し」と「あとでの変更のしやすさ」のための入れ物。", "kid": "同じ値（名前やファイルの場所など）をスクリプトのあちこちで使いたいとき、その値に短い名前を付けておくと、その名前を書くだけで値を呼び出せる。値を変えたくなったときも、変数の中身を1箇所書き換えるだけで、使っている全部の場所に反映される。", "eg": "たとえるなら、変数は「呼び名を付けたラベル」。毎回「株式会社なんとかかんとか山田太郎様」とフルで書く代わりに、「お客様」というラベルを1回決めておけば、以降は「お客様」と書くだけで済む。呼び方を変えたくなったら、ラベルの中身を1回変えるだけでいい。", "terms": [["変数", "値に名前を付けて、後から呼び出せるようにする入れ物"], ["$name", "変数nameの中身を呼び出す書き方"]], "think": "なぜ変数が要るのかがカギ。もし変数が無ければ、同じ値をスクリプトのあちこちに直接書き込むことになり、値を変えたくなったときに全部の場所を1つずつ書き直す必要が出てくる。変数を使えば、値の管理場所が1箇所に集約されるので、書き直しの手間もミスも減る。", "vs": "環境変数と混同しやすいが、シェルスクリプト内の普通の変数は、そのスクリプトの中だけで使える値。exportすれば環境変数として子プロセスにも渡せる（環境変数とPATHのカテゴリ参照）。", "opt": ["正解。変数は、同じ値を何度も書き直さずに、名前を通して繰り返し利用できるようにする仕組み。", "変数を使うこと自体は値の管理のための仕組みであり、実行速度を直接変える機能ではない。", "変数はexportすれば環境変数として子プロセス（別のコマンド）にも渡せるため、コマンドの引数として使うこともできる。", "変数は値の管理のための仕組みであり、コマンドを実行する権限のレベルとは無関係。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">変数の使い回し</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">name=\"suzuki\"</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1回だけ定義</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">$name</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">何度でも呼出</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">値を変更</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1箇所だけ</text></svg>"}'),

  ('linux-q80', 'シェルスクリプトの入り口',
   'シェルスクリプトで「もしファイルが存在すればAをする、存在しなければBをする」のように、状況によって処理を変えたいときに使う考え方は何か。',
   NULL::text,
   '["条件分岐（状況に応じて実行する処理を変える仕組み）", "パイプ（前のコマンドの出力を次のコマンドの入力につなぐ仕組み）", "リダイレクト（出力先をファイルなどに切り替える仕組み）", "シバン（実行するプログラムを指定する目印）"]',
   0, '[0]', 'single',
   '{"asked": "「状況によって処理を変える」考え方の名前を問う問題。", "point": "「もし〜なら」という判断で処理を変えるのが条件分岐。", "kid": "スクリプトは常に同じ処理を上から順番にやるだけではない。「もしファイルがあればAをする、無ければBをする」というふうに、状況によってやることを変えたいことがある。この「もし〜なら」という判断の仕組みを条件分岐と呼ぶ。", "eg": "たとえるなら、条件分岐は「もし雨が降っていたら傘を持つ、降っていなければ持たない」という日常の判断そのもの。スクリプトの中でも、状況を確認してから次の行動を選ぶ。", "terms": [["条件分岐", "状況を確認し、その結果によって実行する処理を変える仕組み"], ["if", "条件分岐を書くときによく使われる、シェルスクリプトの構文の名前"]], "think": "なぜ条件分岐が必要かがカギ。スクリプトを「毎回まったく同じ手順」でしか動かせないなら、状況が変わるたびに別々のスクリプトを用意する羽目になる。条件分岐があれば、1つのスクリプトの中で「状況に応じて枝分かれする」処理を書けるので、様々な場面に1つのスクリプトで対応できる柔軟さが生まれる。", "vs": "パイプと混同しやすいが、パイプは「前のコマンドの結果を次に渡す」という決まった一本道のつながりで、条件分岐のように「状況で道が分かれる」仕組みとは別物。", "opt": ["正解。条件分岐は、状況に応じて実行する処理を変える仕組み。", "パイプは出力を次のコマンドに渡す決まった一本道の仕組みで、状況によって処理を切り替える仕組みではない。", "リダイレクトは出力先をファイルに切り替える仕組みで、状況に応じて処理内容そのものを変えるわけではない。", "シバンは実行するプログラムを指定する目印で、処理を状況によって分けるための仕組みではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">条件分岐の分かれ道</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"38\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">ファイルあり</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">Aの処理を実行</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"38\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">ファイルなし</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">Bの処理を実行</text></svg>"}'),

  ('linux-q81', 'シェルスクリプトの入り口',
   'QAエンジニアが「毎回手動でテスト環境をセットアップしてから自動テストを実行する」作業をシェルスクリプトにまとめると、どんな利点が期待できるか。',
   NULL::text,
   '["手順の抜け漏れやタイプミスによる作業のばらつきが減る", "テスト対象のソフト自体のバグが自動的に無くなる", "テストの実行結果が常に「成功」になるよう保証される", "スクリプトにした瞬間から、テストの内容を考える必要が無くなる"]',
   0, '[0]', 'single',
   '{"asked": "手作業をシェルスクリプトに自動化する利点を問う問題。", "point": "自動化の一番の利点は「毎回同じ手順を、寸分違わず再現できる」こと。", "kid": "手作業だと、その日の疲れや慌ただしさで、手順を1つ飛ばしたり、コマンドを打ち間違えたりすることがある。シェルスクリプトにまとめておけば、書いた通りの手順が毎回そのまま実行されるので、こうした人為的なばらつきが減る。", "eg": "たとえるなら、手作業は「レシピを見ながら毎回自己流で少しアレンジしてしまう料理」。スクリプト化は「レシピ通りに寸分違わず再現してくれる自動調理器」。同じ手順を毎回まったく同じ精度で繰り返せる。", "terms": [["自動化", "手作業で繰り返していた手順を、プログラムに任せて再現性を上げること"], ["再現性", "同じ手順を実行すれば、毎回同じ結果になること"]], "think": "なぜQA実務との相性が良いのかがカギ。テストは「同じ条件で毎回同じように動かして結果を比べる」ことが命。手作業でセットアップ手順にばらつきがあると、テストの結果が本当にソフトのせいなのか、セットアップ手順のミスのせいなのか切り分けにくくなる。シェルスクリプトで手順を固定すれば、セットアップ由来のばらつきを減らし、テスト結果の信頼性を上げられる。", "vs": "「自動化すればバグが無くなる」という誤解に注意。自動化が減らすのはあくまで「作業手順のばらつき」であり、テスト対象のソフト自体の品質を直接変えるわけではない。", "opt": ["正解。シェルスクリプトで手順を固定することで、手順の抜け漏れやタイプミスによる作業のばらつきが減る。", "自動化されるのはセットアップやテスト実行の手順であり、テスト対象のソフト自体のバグが自動的に消えるわけではない。", "自動化しても、テストが失敗すべき状況では引き続き失敗が正しく検出される必要があり、常に成功が保証されるわけではない（むしろ保証されては困る）。", "スクリプト化しても、何をどうテストするかという設計・判断は引き続き人間が考える必要がある。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">手作業とスクリプト化</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">手作業</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">毎回ばらつき</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">スクリプト化</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">手順を固定</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">再現性</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">安定した結果</text></svg>"}'),

  ('linux-q82', 'シェルスクリプトの入り口',
   '作成したシェルスクリプトのファイルを `./setup.sh` のように実行しようとしたら「権限がありません」というエラーが出た。原因として最も適切なものはどれか。',
   NULL::text,
   '["ファイルに実行権限(x)が付いていない", "ファイルの中身が空だから", "ファイル名の拡張子が.shではないから", "ファイルの所有者がrootではないから常に実行できない"]',
   0, '[0]', 'single',
   '{"asked": "シェルスクリプトを実行しようとして権限エラーになる原因を問う問題。", "point": "実行しようとしたら弾かれた、なら、まず実行権限(x)を疑う。", "kid": "ファイルには、読む権限(r)・書く権限(w)に加えて、実行する権限(x)がある。スクリプトファイルを作った直後は、この実行権限が付いていないことが多い。実行権限が無いと、そのファイルを「プログラムとして動かす」ことができず、エラーになる。", "eg": "たとえるなら、実行権限は「このドアを開けて中に入っていい」という許可証。中に何が書いてある（中身は正しい）としても、許可証（実行権限）が無ければドアは開けてもらえない。", "terms": [["実行権限(x)", "そのファイルをプログラムとして実行してよいかを示す権限"], ["chmod", "ファイルの権限を変更するコマンド"]], "think": "なぜ権限とシェルスクリプトがつながるのかがカギ（権限とユーザーのカテゴリの復習接続）。ファイルを新しく作ると、多くの場合は実行権限が付かない状態で作られる。中身がどれだけ正しいシェルスクリプトでも、OSは実行権限という許可証を確認してから実行を許可するかどうか判断する。だから、権限とユーザーのカテゴリで学んだrwxの仕組みが、ここでもそのまま関わってくる。", "vs": "「拡張子が実行できるかどうかを決める」という誤解に注意。Linuxでは拡張子(.shなど)自体は実行の可否に関係なく、あくまで実行権限(x)の有無で判断される。", "opt": ["正解。ファイルに実行権限(x)が付いていないと、`./`で実行しようとした際に権限エラーになる。", "ファイルの中身が空でも、実行権限さえ付いていればエラーメッセージ自体は「権限がありません」にはならない（別のエラーになる）。", "Linuxでは拡張子は実行の可否に直接関係せず、実行権限(x)の有無で判断される。", "所有者がrootでなくても、自分がそのファイルの所有者であれば実行権限を自分に付与して実行でき、rootである必要はない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">実行権限のチェック</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">setup.sh</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">中身は正しい</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">実行権限(x)?</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">無ければ拒否</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">実行</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">権限があれば可</text></svg>"}'),

  ('linux-q83', 'ログとトラブルシューティング',
   'プログラムが動いている間、あとから見返せるように記録を残しておくことを「ログを取る」という。なぜわざわざログという記録を残しておくのか、その一番の理由として適切なものはどれか。',
   NULL::text,
   '["問題が起きたとき、後から何が起きたかを調べる手がかりにするため", "ログを残しておくと、プログラムの実行速度が上がるため", "ログを残さないと、プログラムがそもそも起動できない仕組みになっているため", "ログはユーザーへの広告表示のために使われる仕組みだから"]',
   0, '[0]', 'single',
   '{"asked": "ログを残す一番の理由を問う問題。", "point": "ログの役割は「あとから振り返るための記録」。", "kid": "プログラムは動いている瞬間はいろいろな処理をしているけれど、何もしなければその様子は誰の目にも残らず消えていく。ログは、その「何が起きたか」を文字として書き残しておく記録。何か問題が起きたとき、このログを見返せば「いつ、何が、どうなったか」を後から調べられる。", "eg": "たとえるなら、ログは「防犯カメラの映像」。何も無ければ見返すことは無いけれど、何かトラブルが起きたときに映像を見返せば、何が起きたかを後から確認できる。", "terms": [["ログ", "プログラムの動作を後から確認できるように残しておく記録"], ["トラブルシューティング", "問題の原因を調べて解決すること"]], "think": "なぜ記録を残しておく必要があるのかがカギ。プログラムが動いている瞬間をリアルタイムで人間がずっと見張っているのは現実的ではない。問題は大抵、誰も見ていないタイミングで起きる。ログという記録を残しておけば、問題が起きた「後」からでも、その瞬間に何が起きていたかを再現できる。これが無いと、原因調査は勘に頼るしかなくなる。", "vs": "「ログはエラーのときだけ残す」という誤解に注意。正常に動いているときの記録も含めてログに残すことで、「いつもと違う」という異常への気づきや、正常時との比較がしやすくなる。", "opt": ["正解。ログは、問題が起きたとき後から何が起きたかを調べる手がかりにするために残す。", "ログを残すこと自体は記録のための処理であり、プログラム本体の実行速度を上げる働きはない。", "多くのプログラムはログを残さなくても起動自体はできる。ログはあくまで記録のための補助的な仕組み。", "ログはプログラムの動作記録であり、ユーザーへの広告表示のための仕組みではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ログの役割</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プログラム動作</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">その瞬間</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ログに記録</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">文字として保存</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">後から確認</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">原因調査</text></svg>"}'),

  ('linux-q84', 'ログとトラブルシューティング',
   '多くのLinuxシステムでは、様々なプログラムのログが `/var/log` というディレクトリにまとめて置かれる。この「置き場所を統一する」という考え方が役に立つ理由として最も適切なものはどれか。',
   NULL::text,
   '["どこを探せばログがあるか毎回迷わずに済み、調査がしやすくなる", "1つのディレクトリにまとめると、ログの中身が自動的に要約される", "置き場所を統一すると、ログを残す必要自体が無くなる", "`/var/log`に置かれたログは、二度と削除できなくなる"]',
   0, '[0]', 'single',
   '{"asked": "ログの置き場所を`/var/log`に統一する意味を問う問題。", "point": "置き場所が決まっていることが、探す手間を減らす一番の価値。", "kid": "もしプログラムごとにログの置き場所がバラバラだったら、問題が起きるたびに「このプログラムのログはどこだっけ」と毎回探し回ることになる。`/var/log`という決まった場所に置くルールがあれば、迷わずそこを見に行けば大抵の手がかりが見つかる。", "eg": "たとえるなら、`/var/log`は「会社の書類は全部この棚にまとめて保管する」という共通ルールの棚。棚の場所が決まっていれば、必要な書類を探すときにオフィス中を探し回らなくて済む。", "terms": [["/var/log", "多くのログファイルがまとめて置かれる、Linuxで決まった場所"], ["ファイルシステムの本質", "ディレクトリという置き場所自体の考え方（ファイルシステムの本質カテゴリの復習接続）"]], "think": "なぜ「置き場所の統一」が価値を持つのかがカギ。トラブルが起きたときは、一刻も早く原因を調べたい状況が多い。もし置き場所がバラバラだと、原因調査の前に「どこにログがあるか」を探す時間が余計にかかってしまう。`/var/log`という共通の置き場所ルールがあることで、その探す時間をゼロに近づけられる。", "vs": "「1箇所にまとめると自動で要約される」という誤解に注意。`/var/log`はあくまで置き場所のルールであり、そこに集まったログの中身を自動で読みやすく要約してくれるわけではない（それは別のログ収集ツールの役割）。", "opt": ["正解。置き場所が統一されていることで、どこを探せばログがあるか毎回迷わずに済み、調査がしやすくなる。", "`/var/log`はあくまで置き場所であり、中身を自動で要約する機能自体は持たない。", "置き場所を統一しても、プログラムがログを残す意味（後から振り返るための記録）自体は変わらず必要とされ続ける。", "`/var/log`に置かれたログも、他のファイルと同じように削除・整理できる。二度と消せなくなるわけではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">/var/logという置き場所</text><rect x=\"140\" y=\"32\" width=\"60\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"170\" y=\"49\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">/var/log</text><line x1=\"170\" y1=\"58\" x2=\"55.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"10.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"55.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">appA.log</text><line x1=\"170\" y1=\"58\" x2=\"285.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"240.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"285.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">appB.log</text></svg>"}'),

  ('linux-q85', 'ログとトラブルシューティング',
   '`journalctl`のようなコマンドは、システム全体のいろいろなプログラムのログを1箇所にまとめて検索・閲覧できるようにしてくれる。このような仕組みが役に立つ理由として最も適切なものはどれか。',
   NULL::text,
   '["複数のプログラムをまたいで、時系列で何が起きたかを追いやすくなる", "ログを収集する仕組みを使うと、エラー自体が二度と発生しなくなる", "ログ収集の仕組みを使うと、プログラムのソースコードが自動的に修正される", "1箇所にまとめると、個別のプログラムのログファイルは完全に不要になる"]',
   0, '[0]', 'single',
   '{"asked": "システム全体のログをまとめて閲覧できる仕組みが役立つ理由を問う問題。", "point": "複数のプログラムをまたいだ「時系列」でトラブルを追えることが最大の価値。", "kid": "1つのトラブルは、複数のプログラムが絡み合って起きることがよくある。プログラムごとに別々のログを1つずつ見比べていると、時間の流れを追いにくい。journalctlのような仕組みは、いろいろなプログラムのログを1箇所にまとめて、時系列で並べて見られるようにしてくれる。", "eg": "たとえるなら、複数の防犯カメラ（各プログラムのログ）の映像を、時刻順に1本のタイムラインとしてまとめて見られる監視室のようなもの。バラバラの映像を見比べるより、何が先に起きて何が後に起きたか追いやすい。", "terms": [["journalctl", "システム全体のログをまとめて検索・閲覧できるコマンドの代表例"], ["時系列", "出来事が起きた順番。複数のログをまたいで追うときに重要"]], "think": "なぜ「まとめる」ことが調査に効くのかがカギ。トラブルの原因が、実はテスト対象のプログラムではなく、その裏で動いている別のサービスにあった、ということもよくある。プログラムごとにバラバラのログを個別に開いて時刻を突き合わせるのは手間がかかる。まとめて時系列に見られる仕組みがあれば、「Aが失敗する直前に、Bで何が起きていたか」をすぐに追える。QA実務でのテスト失敗調査でも、この時系列の視点が役立つ。", "vs": "「まとめるとエラーが消える」という誤解に注意。ログ収集の仕組みが変えるのは「見やすさ・追いやすさ」であって、エラーそのものの発生原因を直接無くすわけではない。", "opt": ["正解。複数のプログラムをまたいで、時系列で何が起きたかを追いやすくなることが最大の利点。", "ログをまとめて見やすくする仕組みであり、エラー発生自体を防ぐ仕組みではない。", "ログ収集の仕組みはあくまで記録の閲覧を助けるものであり、プログラムのソースコードを自動修正する機能ではない。", "まとめて閲覧できるようになっても、個別のログファイル自体が無くなるわけではなく、収集元として引き続き存在することが多い。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">複数プログラムのログを時系列に</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プログラムA</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ログ</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プログラムB</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ログ</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">journalctl</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">時系列でまとめ表示</text></svg>"}'),

  ('linux-q86', 'ログとトラブルシューティング',
   'ログには「INFO（情報）」「WARNING（警告）」「ERROR（エラー）」のようなレベル分けがされていることが多い。このレベル分けが役に立つ理由として最も適切なものはどれか。',
   NULL::text,
   '["深刻さに応じて絞り込めるので、重大な問題だけをすばやく見つけられる", "レベルを分けると、ログファイルのサイズが自動的に小さくなる", "レベル分けをすると、エラーが二度と起きなくなる", "レベルは見た目を装飾するためだけの飾りで、実用上の意味は無い"]',
   0, '[0]', 'single',
   '{"asked": "ログのレベル分け（INFO/WARNING/ERRORなど）が役立つ理由を問う問題。", "point": "レベル分けの価値は「深刻さで絞り込める」こと。", "kid": "ログには、ただの経過報告（INFO）から、注意が必要なもの（WARNING）、はっきり問題が起きたもの（ERROR）まで、いろいろな深刻さの記録が混ざっている。レベル分けがされていれば、「ERRORだけ見せて」と絞り込んで、重大な問題だけをすばやく見つけられる。", "eg": "たとえるなら、レベル分けは「メールの重要度マーク」。全部のメールを同じ扱いで読み返すのは大変だけど、「重要」マークが付いたメールだけ先に確認すれば、緊急のものを見逃しにくい。", "terms": [["ログレベル", "記録の深刻さを示す分類。INFO・WARNING・ERRORなど"], ["絞り込み", "大量の記録から、必要なものだけを選び出すこと"]], "think": "なぜレベル分けが調査の効率を上げるのかがカギ。1つのプログラムは、正常に動いているときも大量のINFOログを出し続けることが多く、その中に本当に問題のあるERRORが埋もれてしまいがちになる。レベルで絞り込めれば、大量の正常な記録をかき分けずに、まず深刻な記録から確認できる。テキスト処理カテゴリのgrepで文字列を絞り込むのと同じ発想で、レベルという軸でログを絞り込んでいる。", "vs": "「レベルを分けるとファイルサイズが減る」という誤解に注意。レベル分けは記録の性質を示す印であって、記録そのものの量やファイルサイズを直接減らす仕組みではない。", "opt": ["正解。深刻さに応じて絞り込めるので、重大な問題だけをすばやく見つけられる。", "レベル分け自体は記録に印を付ける仕組みであり、ファイルサイズを自動的に小さくする機能ではない。", "レベル分けは記録の見やすさを上げる仕組みであり、エラーの発生原因そのものを取り除く機能ではない。", "レベルは深刻さに応じて絞り込みや対応の優先度を判断するための実用的な情報で、単なる見た目の飾りではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ログレベルで絞り込む</text><rect x=\"37.5\" y=\"40.0\" width=\"50\" height=\"80.0\" rx=\"3\" fill=\"#8892a4\" stroke=\"none\"/><text x=\"62.5\" y=\"134\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">INFO</text><rect x=\"125.0\" y=\"80.0\" width=\"50\" height=\"40.0\" rx=\"3\" fill=\"#c9a04a\" stroke=\"none\"/><text x=\"150.0\" y=\"134\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">WARN</text><rect x=\"212.5\" y=\"100.0\" width=\"50\" height=\"20.0\" rx=\"3\" fill=\"#c47070\" stroke=\"none\"/><text x=\"237.5\" y=\"134\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ERROR</text><line x1=\"30\" y1=\"120\" x2=\"310\" y2=\"120\" stroke=\"#2a2f3f\"/></svg>"}'),

  ('linux-q87', 'ログとトラブルシューティング',
   '自動テストが失敗したとき、テストコード自体を疑う前に、まずテスト対象のアプリケーションやCI環境のログを確認するとよいと言われる。この順序が推奨される理由として最も適切なものはどれか。',
   NULL::text,
   '["ログを見ることで、テスト自体の不具合か環境側の問題かを早く切り分けられるから", "ログを見なければ、テストコードを一切修正できない決まりになっているから", "ログを見ると、テストコードが自動的に書き直されるから", "ログを確認する作業には、テストの再実行より時間がかかるから避けるべきだから"]',
   0, '[0]', 'single',
   '{"asked": "テスト失敗時にまずログを確認する理由を問う問題。", "point": "ログを先に見る目的は「疑う場所を早く絞り込む」こと。", "kid": "テストが失敗したとき、原因は「テストコード自体の書き方」「テスト対象のアプリのバグ」「CI環境の一時的な不調」など、いくつも考えられる。いきなりテストコードを疑って直し始めると、実は環境側の問題だった場合、直したのに直らないという無駄が起きる。先にログを見れば、どこに問題がありそうか手がかりを早く得られる。", "eg": "たとえるなら、体調不良のとき、いきなり自己判断で薬を飲むより、まず熱を測ったり症状を記録したり（ログを確認したり）してから対処法を決めるほうが、的外れな対処を避けやすいのと同じ。", "terms": [["切り分け", "問題の原因がどこにあるかを絞り込んでいく作業"], ["CI環境", "自動テストなどを実行する、日常的に使っている手元の環境とは別の実行環境"]], "think": "なぜログが「切り分け」の近道になるのかがカギ。テスト失敗の報告だけでは「何が」失敗したかは分かっても「なぜ」失敗したかまでは分からないことが多い。ログには、失敗の直前に何が起きていたかの手がかり（環境変数の設定ミス、依存パッケージのエラー、権限エラーなど、このドリルで扱ってきた様々な仕組みの不具合）が残っていることが多く、テストコードを疑う前にこの手がかりを確認することで、無駄な修正を避けられる。QA実務でこの発想が特に活きる。", "vs": "「ログを見ることが目的化する」ことと混同しないよう注意。ログを見る目的はあくまで「疑う場所を早く絞り込む」ことで、ログを読むこと自体がゴールではない。", "opt": ["正解。ログを見ることで、テスト自体の不具合か環境側の問題かを早く切り分けられる。", "ログを見なくてもテストコードの修正自体は可能で、ログ確認が修正の絶対条件というわけではない（あくまで効率のための推奨）。", "ログを確認する行為自体がテストコードを自動的に書き換えることはない。", "ログ確認は、無駄な再修正・再実行を減らすことでむしろ全体の時間短縮につながる、推奨される手順。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">テスト失敗時の切り分け</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">テスト失敗</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">原因不明</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ログ確認</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">手がかり</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">原因を切り分け</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">コード or 環境</text></svg>"}'),

  ('linux-q88', 'ログとトラブルシューティング',
   'サーバーで動き続けているプログラムのログファイルは、時間とともに行がどんどん追加されていく。この「増え続けるファイルの末尾だけをリアルタイムに見る」ときに使われるコマンドはどれか。',
   NULL::text,
   '["tail -f（ファイルの末尾を表示し、追加された行もリアルタイムに追う）", "head（ファイルの先頭だけを表示する）", "rm（ファイルを削除する）", "mkdir（ディレクトリを作成する）"]',
   0, '[0]', 'single',
   '{"asked": "増え続けるログファイルの末尾をリアルタイムに追うコマンドを問う問題。", "point": "「今まさに増えている末尾」を追いたいなら `tail -f`。", "kid": "動き続けているプログラムのログは、新しい行がどんどん末尾に追加されていく。`tail -f`を使うと、ファイルの末尾を表示したまま、新しく追加された行が出てくるたびにそれもリアルタイムで表示し続けてくれる。", "eg": "たとえるなら、tail -fは「ライブ配信のコメント欄を眺め続ける」ようなもの。新しいコメント（ログの行）が来るたびに、画面に流れて追加されていくのをそのまま見続けられる。", "terms": [["tail", "ファイルの末尾（後ろの部分）だけを表示するコマンド"], ["-f（follow）", "ファイルへの追記をリアルタイムに追いかけ続けるオプション"]], "think": "なぜ末尾だけを追うのかがカギ。動き続けているログファイルは巨大になりがちで、`cat`で全部を毎回表示していたら、最新の状況を知るまでに時間がかかってしまう。`tail`は末尾（最新の記録）だけを表示し、さらに`-f`を付けることで、新しい行が追加されるたびにそれをそのまま流し続けてくれるので、今まさに何が起きているかをリアルタイムに把握できる。", "vs": "headと混同しやすいが、headはファイルの先頭（古い記録）だけを見るコマンドで、リアルタイムに追加を追う機能は無い。tailは末尾（新しい記録）を見るという点で正反対の役割。", "opt": ["正解。`tail -f`はファイルの末尾を表示し、新しく追加された行もリアルタイムに追い続けられる。", "headはファイルの先頭部分だけを表示するコマンドで、末尾のリアルタイムな追跡はできない。", "rmはファイルを削除するコマンドで、ログを読む用途とは正反対。", "mkdirはディレクトリを新しく作るコマンドで、ログファイルの中身を追う用途ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">tail -fでリアルタイムに追う</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ログファイル</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">増え続ける</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">tail -f</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">末尾を追跡</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">画面</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">新しい行が流れる</text></svg>"}'),

  ('linux-q89', 'ディスクとストレージの基礎',
   '1台の物理ディスクを、用途ごとに複数の区画に分けて使うことがある。この「1台のディスクを複数の区画に分ける」考え方を何と呼ぶか。',
   NULL::text,
   '["パーティション（1台のディスクを複数の区画に分ける単位）", "マウント（ディレクトリツリーの中にディスクの中身を組み込む操作）", "inode（ファイルの実体を管理する番号）", "シバン（実行するプログラムを指定する目印）"]',
   0, '[0]', 'single',
   '{"asked": "1台のディスクを複数の区画に分ける考え方の名前を問う問題。", "point": "1台のディスクを分割した区画そのものがパーティション。", "kid": "1台の大きなディスクを、そのまま丸ごと1つの用途に使わず、いくつかの区画に区切って使うことがある。この区切られた1つ1つの区画をパーティションと呼ぶ。それぞれのパーティションに別々のファイルシステムを入れることもできる。", "eg": "たとえるなら、パーティションは「1つの大きな冷蔵庫を、野菜室・冷凍室・チルド室に仕切る」ようなもの。同じ1台の冷蔵庫（ディスク）でも、区画ごとに違う使い方ができる。", "terms": [["パーティション", "1台の物理ディスクを分割した、それぞれ独立して扱える区画"], ["ファイルシステム", "パーティションの中身をどう管理するかの仕組み（ファイルシステムの本質カテゴリの復習接続）"]], "think": "なぜディスクを区画に分けるのかがカギ。1台のディスクを丸ごと1つの用途にしてしまうと、例えば一部が壊れたときに全体が巻き添えになったり、システム用のデータと自分のデータが同じ場所に混在して整理しにくくなったりする。パーティションで区切っておくことで、区画ごとに管理や影響範囲を分けやすくなる。", "vs": "マウントと混同しやすいが、パーティションは「ディスクをどう区切るか」という区画分けの話で、マウントは「区切った区画をどこに組み込んで見せるか」という別の操作（ディスクとストレージのカテゴリの他の問題を参照）。", "opt": ["正解。パーティションは、1台の物理ディスクを複数の区画に分ける単位。", "マウントはパーティションの中身をディレクトリツリーに組み込む操作で、区画そのものを作る話とは別。", "inodeはファイルの実体を管理する番号で、ディスクを区画に分ける単位とは別の概念。", "シバンは実行するプログラムを指定する目印で、ディスクの区画分けとは無関係。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1台のディスクを分ける</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">ディスク全体</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">1台</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">パーティション分け</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">区画ごとに分割</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">複数の区画</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">それぞれ独立</text></svg>"}'),

  ('linux-q90', 'ディスクとストレージの基礎',
   'Linuxには ext4 や xfs のような、複数の種類のファイルシステムが存在する。1種類に統一されていない理由として最も適切なものはどれか。',
   NULL::text,
   '["用途によって重視したい性能や特性が違い、それぞれに向き不向きがあるから", "ファイルシステムは1種類だけでは技術的にファイルを保存できないから", "複数の種類があることに実用上の意味はなく、単なる歴史的な名残でしかないから", "ファイルシステムの種類が違うと、保存できるファイルの数に上限が無くなるから"]',
   0, '[0]', 'single',
   '{"asked": "複数のファイルシステムが存在する理由を問う問題。", "point": "複数あるのは「重視したい特性」が用途によって違うから。", "kid": "ファイルシステムは、ファイルをディスクの上でどう整理して管理するかの設計。設計の仕方によって、「小さいファイルの読み書きが速い」「巨大なファイルの扱いが得意」「壊れにくさを重視している」など、得意なことが変わってくる。だから用途に合わせて選べるように、複数の種類が用意されている。", "eg": "たとえるなら、ファイルシステムの種類は「収納用品の種類」。小物をたくさん整理するなら仕切りの多い引き出し、大きな荷物をまとめるなら大きな箱、というふうに、しまいたいものによって向いている収納が違うのと同じ。", "terms": [["ファイルシステム", "ディスク上でファイルをどう整理・管理するかの設計方式"], ["ext4/xfs", "Linuxでよく使われるファイルシステムの種類の例"]], "think": "なぜ1種類に統一されないのかがカギ。もしファイルシステムが1種類しか無ければ、あらゆる用途（小さいファイルが大量にある環境、巨大な動画ファイルを扱う環境、信頼性を最優先したい環境など）を1つの設計でまかなわなければならず、どこかで無理が出る。複数の種類が存在することで、その環境に合った特性を選べるようになっている。", "vs": "「種類が違うと保存できる中身も変わる」という誤解に注意。どのファイルシステムを使っても、ファイルという概念自体（ファイルシステムの本質カテゴリで学んだ木構造やinodeの考え方）は共通しており、違うのはその管理の設計・得意分野。", "opt": ["正解。用途によって重視したい性能や特性が違うため、複数の種類のファイルシステムが用意されている。", "ファイルシステムはどの種類であってもファイルを保存する仕組みとして機能し、1種類では技術的に不可能というわけではない。", "種類によって得意な用途が異なり、環境に合わせて選べるという実用上の意味がある。", "ファイルシステムの種類によって保存できるファイル数の上限の考え方は異なるが、「上限が無くなる」という単純な話ではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">ファイルシステムの向き不向き</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">ext4系</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">小さいファイルが多い環境</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">汎用的でよく使われる</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">xfs等</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">巨大ファイルの扱いが得意</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">特定用途で有利</text></svg>"}'),

  ('linux-q91', 'ディスクとストレージの基礎',
   '「ファイルシステムの本質」カテゴリで、マウントは「ディレクトリツリーの中にディスクの中身を組み込む操作」と学んだ。この仕組みのおかげで実現できていることとして最も適切なものはどれか。',
   NULL::text,
   '["複数の物理ディスクの中身を、1つのつながった木構造として扱える", "マウントすると、複数のディスクが物理的に1台に融合する", "マウントは、ディスクの中身をすべて暗号化する操作である", "マウントしないと、ディスクの容量が半分になってしまう"]',
   0, '[0]', 'single',
   '{"asked": "マウントという仕組みのおかげで実現できていることを問う問題。", "point": "マウントの価値は「複数の実体を、1つの木構造として見せる」こと。", "kid": "パソコンには、複数のディスクやパーティションが物理的には別々に存在していることがある。マウントという操作をすると、その別々のディスクの中身を、まるで1本の同じディレクトリツリーの中の一部であるかのように扱えるようになる。ユーザーからは、どこからどこまでが別のディスクか意識せずに、1つのツリーとして操作できる。", "eg": "たとえるなら、マウントは「本館とは別の建物にある倉庫を、本館の3階の一室として使えるように繋げる」ようなもの。物理的には別の建物でも、案内表示（パス）上は本館の一部として自然に歩いて行ける。", "terms": [["マウント", "ディスクやパーティションの中身を、ディレクトリツリーの特定の場所に組み込む操作"], ["マウントポイント", "組み込み先になるディレクトリの場所"]], "think": "なぜ複数のディスクを1つの木構造に見せる必要があるのかがカギ。もしディスクごとに全く別々の木構造（AドライブやBドライブのような別世界）で管理されていたら、ファイルの場所を扱うたびに「どのディスクか」を毎回意識する必要が出てくる。マウントの仕組みがあることで、複数の物理的な実体があっても、利用者からは1本の連続したディレクトリツリーとして自然に扱える。", "vs": "「マウントするとディスクが物理的に1つになる」という誤解に注意。マウントはあくまで論理的な組み込み（木構造の中での見え方の統合）であり、物理的にディスクが融合するわけではない。", "opt": ["正解。マウントによって、複数の物理ディスクの中身を1つのつながった木構造として扱えるようになる。", "マウントは論理的にディレクトリツリーへ組み込む操作であり、物理的にディスクが1台に融合するわけではない。", "マウントはディスクの中身をディレクトリツリーに組み込む操作であり、暗号化を行う操作ではない。", "マウントするかどうかは、木構造への組み込み方の話であり、ディスクの物理的な容量自体を変える操作ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">マウントで1つの木構造に</text><rect x=\"140\" y=\"32\" width=\"60\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"170\" y=\"49\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">/</text><line x1=\"170\" y1=\"58\" x2=\"55.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"10.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"55.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">/(ルート)</text><line x1=\"170\" y1=\"58\" x2=\"285.0\" y2=\"92\" stroke=\"#2a2f3f\"/><rect x=\"240.0\" y=\"92\" width=\"90\" height=\"26\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"285.0\" y=\"109\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">/mnt(別ディスク)</text></svg>"}'),

  ('linux-q92', 'ディスクとストレージの基礎',
   'ディスクの空き容量を増やそうと大きなファイルを削除したのに、確認してみると空き容量がほとんど増えていないことがある。この現象が起きる原因として考えられるものはどれか。',
   NULL::text,
   '["まだ動いているプロセスがそのファイルを開いたままにしている", "ファイルを削除すると、必ず別のファイルが自動的に作られるから", "ディスクの空き容量は削除しても絶対に変化しない仕組みになっているから", "ファイルシステムの種類を変えない限り、削除は反映されないから"]',
   0, '[0]', 'single',
   '{"asked": "ファイルを削除しても空き容量が増えない現象の原因を問う問題。", "point": "「消したはずなのに空かない」なら、まだ誰かが掴んでいないか疑う。", "kid": "ファイルを削除する操作は、ディレクトリツリーからその名前を取り除くだけのことが多い。もし、あるプロセス（プログラムの実行中の1つ）がまだそのファイルを開いたまま使っていると、実体のデータはディスク上に残り続け、そのプロセスが使い終わる（ファイルを閉じる）まで、本当の意味での容量は空かないことがある。", "eg": "たとえるなら、図書館の目録（ディレクトリ）からある本のカードを抜いても、その本を今まさに誰かが借りて読んでいる（プロセスが開いている）なら、本棚のスペース（ディスク容量）自体はまだ空かないのと同じ。", "terms": [["プロセスがファイルを開いている", "プロセスが使用中のファイルを掴んでいる状態（プロセスという考え方カテゴリの復習接続）"], ["削除", "ディレクトリからファイルの名前を取り除く操作"]], "think": "なぜ削除してもすぐ空かないことがあるのかがカギ。ファイルシステムの本質カテゴリで学んだように、ファイル名とファイルの実体（inode）は別物として管理されている。削除という操作は、多くの場合まず「名前」を取り除くだけで、実体のデータは、それを開いているプロセスが全員手を離すまで残り続ける仕組みになっている。ログファイルを出力し続けているプロセスなどで、この現象がよく起きる。", "vs": "「削除コマンドが失敗した」という誤解に注意。削除コマンド自体は正常に成功していることが多く、原因は「まだ使用中のプロセスが実体を掴んだままである」という、削除とは別の要因であることが多い。", "opt": ["正解。まだ動いているプロセスがそのファイルを開いたままにしていると、実体の容量はすぐには解放されない。", "ファイルを削除しても、削除の結果として別のファイルが自動的に作られるわけではない。", "削除の反映は状況によりタイミングが異なることはあるが、絶対に変化しないという仕組みではない。", "ファイルシステムの種類を変えなくても削除自体は反映されるのが基本で、種類変更が条件というわけではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"24\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">削除してもすぐ空かない理由</text><rect x=\"20\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"65.33333333333334\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">rmで削除</text><text x=\"65.33333333333334\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">名前を除去</text><line x1=\"112.66666666666667\" y1=\"70\" x2=\"122.66666666666667\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"124.66666666666667\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170.0\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセスが開いたまま</text><text x=\"170.0\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">実体は残る</text><line x1=\"217.33333333333334\" y1=\"70\" x2=\"227.33333333333334\" y2=\"70\" stroke=\"#60a5fa\" marker-end=\"url(#arrow)\"/><rect x=\"229.33333333333334\" y=\"50\" width=\"90.66666666666667\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"274.6666666666667\" y=\"66\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\" font-weight=\"normal\">プロセス終了後</text><text x=\"274.6666666666667\" y=\"82\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">容量が解放</text></svg>"}'),

  ('linux-q93', 'ディスクとストレージの基礎',
   '「ディスク全体の空き容量を確認したい」ときと、「どのディレクトリが容量を多く使っているか調べたい」ときでは、それぞれ役割の異なるコマンドを使う。この2つの目的の違いを最もよく表しているものはどれか。',
   NULL::text,
   '["全体の空き容量を見る視点と、内訳をディレクトリ単位で見る視点は別物", "この2つの目的は実質同じ内容を尋ねているので、同じ結果になる", "内訳を見る前には、必ずディスクを一度フォーマットする必要がある", "空き容量の確認は、rootユーザーでなければ絶対にできない"]',
   0, '[0]', 'single',
   '{"asked": "ディスク全体の空き容量確認と、ディレクトリ別の内訳確認の視点の違いを問う問題。", "point": "「全体でどれだけ空いているか」と「何が容量を食っているか」は別の問い。", "kid": "「ディスクにあとどれだけ空きがあるか」を知りたいときと、「どのフォルダが容量をたくさん使っているのか」を知りたいときでは、聞きたいことがそもそも違う。前者は全体の残量を知りたいだけで内訳には興味が無い。後者は、容量を圧迫している原因（犯人）を探すために内訳を知りたい。", "eg": "たとえるなら、「財布に残高がいくらあるか」を確認するのと、「何にお金を使いすぎたのか、レシートの内訳を確認する」のは別の作業なのと同じ。前者は残高の確認、後者は原因の分析。", "terms": [["df（disk free）", "ディスク全体の空き容量を確認するためのコマンドの代表例"], ["du（disk usage）", "ディレクトリ単位で使用容量の内訳を調べるためのコマンドの代表例"]], "think": "なぜ視点を分けて考える必要があるのかがカギ。「容量が足りない」というトラブルが起きたとき、まず全体の残量を見て「本当に足りていないか」を確認し、次に内訳を見て「何が容量を圧迫しているか」を突き止める、という2段階の調査になることが多い。全体を見る視点と内訳を見る視点は目的が違うため、それぞれに適したコマンドが用意されている。", "vs": "「同じことを尋ねている」という誤解に注意。全体の残量が分かっても、それだけでは何が原因で容量を圧迫しているかは分からず、原因調査には内訳を見る視点が別途必要になる。", "opt": ["正解。全体の空き容量を見る視点と、内訳をディレクトリ単位で見る視点は別物で、それぞれ目的が異なる。", "全体の残量確認と内訳の確認は目的が異なる別の調査であり、同じ結果が返ってくるわけではない。", "容量の内訳を確認するために、ディスクを事前にフォーマットする必要はない。", "空き容量の確認自体は一般ユーザーの権限でも行えることが多く、常にrootユーザーが必須というわけではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">全体を見る vs 内訳を見る</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"38\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">全体の残量</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">ディスク全体の空き</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">内訳の確認</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">ディレクトリ別の使用量</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">原因を突き止める</text></svg>"}'),

  ('linux-q94', 'ディスクとストレージの基礎',
   'システムの起動に必要なファイルを置くパーティションと、ログや一時ファイルなど日常的に増減するデータを置くパーティションを、あえて分けて構成することがある。この分割が役立つ理由として最も適切なものはどれか。',
   NULL::text,
   '["一方の容量が枯渇しても、影響がもう一方まで広がりにくくなる", "パーティションを分けると、ディスク全体の容量が2倍に増える", "パーティションを分けると、ファイルの読み書き速度が理論上無限になる", "分割しないと、そもそもOSを起動すること自体ができない"]',
   0, '[0]', 'single',
   '{"asked": "システム用と可変データ用のパーティションを分ける理由を問う問題。", "point": "分ける目的は「片方のトラブルを、もう片方に波及させない」こと。", "kid": "ログのように日々増え続けるデータを、システムの起動に必要な部分と同じ区画に置いていると、そのログが容量を使い切ったときに、システムの起動に必要な部分まで巻き添えで容量不足になってしまう危険がある。あらかじめ区画（パーティション）を分けておけば、片方が容量いっぱいになっても、もう片方への影響を抑えられる。", "eg": "たとえるなら、家計簿で「生活必需品の予算」と「趣味の出費」の財布を分けておくようなもの。趣味に使いすぎても、生活必需品の予算まで食い込まないようにする工夫と同じ発想。", "terms": [["パーティション分割", "用途ごとにディスクの区画を分けて、影響範囲を切り分ける設計"], ["容量枯渇", "ディスクの空き容量が無くなってしまうこと"]], "think": "なぜ影響範囲を切り分けたいのかがカギ。もしログなど増減の激しいデータと、システムの起動に必要な重要なファイルが同じ区画に同居していると、ログが容量を食いつぶしたときに、システムが起動不能に陥るような深刻な事態にまで発展しかねない。パーティションを分けておけば、増減の激しいデータの区画がいっぱいになっても、それはその区画の中だけの問題にとどまり、システムの根幹には波及しにくくなる。", "vs": "「分割すれば容量が増える」という誤解に注意。パーティション分割はあくまで同じディスクの容量を区画ごとに割り振り直す操作であり、ディスク全体の物理的な容量自体が増えるわけではない。", "opt": ["正解。一方の容量が枯渇しても、影響がもう一方まで広がりにくくなることが分割の一番の利点。", "パーティションを分けても、ディスク全体の物理的な容量が増えるわけではなく、既存の容量を区画ごとに割り振っているだけ。", "パーティション分割自体は読み書き速度を無限にする仕組みではなく、影響範囲を切り分けることが主な目的。", "パーティションを分割しなくてもOS自体は起動できることが多く、分割は必須条件ではなく設計上の工夫の1つ。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" font-size=\"12\" fill=\"#8892a4\" text-anchor=\"middle\" font-weight=\"normal\">システム用と可変データ用を分ける</text><rect x=\"16\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"90\" y=\"46\" font-size=\"11\" fill=\"#60a5fa\" text-anchor=\"middle\" font-weight=\"bold\">システム用</text><text x=\"28\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">起動に必要</text><text x=\"28\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">容量を保護</text><rect x=\"176\" y=\"30\" width=\"148\" height=\"56\" rx=\"6\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"46\" font-size=\"11\" fill=\"#c9a04a\" text-anchor=\"middle\" font-weight=\"bold\">ログ/一時データ用</text><text x=\"188\" y=\"66\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">日々増減する</text><text x=\"188\" y=\"84\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"start\" font-weight=\"normal\">枯渇してもここだけ</text></svg>"}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'linux-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

